-- ============================================================================
-- 图书馆样书 seed:Aesop's Fables (aesop-easy-readers)
-- 生成自 scripts/library/books/aesop-easy-readers.json —— node scripts/library/build-seed.mjs aesop-easy-readers
-- ⚠️ 内容(英文改写 + 中文)须先过审(Aaron/网页版 Claude)再落库(content-review-gate + D9)。
-- 幂等:upsert 书 + 删该书旧句重灌。BEGIN/COMMIT + 前后计数。
-- 章号真实(D12);共 89 章 / 443 句。
-- ============================================================================

BEGIN;

-- 0) 章标题列(方案 A:jsonb,幂等加列)。[{idx,title_en,title_zh}] + visibility(私享层已建,防御性再保一次)。
ALTER TABLE public.library_books
  ADD COLUMN IF NOT EXISTS chapters jsonb NOT NULL DEFAULT '[]'::jsonb;
ALTER TABLE public.library_books
  ADD COLUMN IF NOT EXISTS visibility text NOT NULL DEFAULT 'public';

SELECT 'before' AS phase,
       (SELECT count(*) FROM public.library_books WHERE book_key = 'aesop-easy-readers') AS book_exists,
       (SELECT count(*) FROM public.library_sentences s
          JOIN public.library_books b ON b.id = s.book_id
         WHERE b.book_key = 'aesop-easy-readers') AS sentence_rows;

-- 1) 书目(upsert)
INSERT INTO public.library_books
  (book_key, title, zh_title, author, age_band, age_range, cover,
   intro_en, intro_zh, sentence_count, copyright_note, chapters, is_published, visibility)
VALUES
  ('aesop-easy-readers', 'Aesop''s Fables', '伊索寓言', 'Aesop (retold for learners)',
   '青少年', '12-15岁', '{"c1":"#2f7d6e","c2":"#14532d"}'::jsonb,
   'Aesop''s fables, retold in natural modern American English. Short stories about animals, people, and the choices they make, each one ending in a way that leaves you with something to think about.', '用地道现代美语重述的伊索寓言。动物与人的短故事，每一则都在结尾留下一点值得想的东西。', 443, 'Public-domain fables of Aesop, retold in original modern American English. 伊索寓言属公有领域;本册为面向青少年读者的现代美语改写(措辞原创),非任何现行教材节选。',
   '[{"idx":1,"title_en":"The Hare and the Tortoise","title_zh":"龟兔赛跑"},{"idx":2,"title_en":"The Lion and the Mouse","title_zh":"狮子和老鼠"},{"idx":3,"title_en":"The Fox and the Grapes","title_zh":"狐狸和葡萄"},{"idx":4,"title_en":"The Ant and the Grasshopper","title_zh":"蚂蚁和蚱蜢"},{"idx":5,"title_en":"The Goose That Laid the Golden Eggs","title_zh":"下金蛋的鹅"},{"idx":6,"title_en":"The Cat and the Mice","title_zh":"猫与老鼠"},{"idx":7,"title_en":"The Mischievous Dog","title_zh":"爱咬人的狗"},{"idx":8,"title_en":"The Mice in Council","title_zh":"老鼠开会"},{"idx":9,"title_en":"The Fox and the Crow","title_zh":"狐狸与乌鸦"},{"idx":10,"title_en":"The Wolf and the Lamb","title_zh":"狼与羊羔"},{"idx":11,"title_en":"The Spendthrift and the Swallow","title_zh":"败家子与燕子"},{"idx":12,"title_en":"Mercury and the Woodman","title_zh":"墨丘利与樵夫"},{"idx":13,"title_en":"The Crow and the Pitcher","title_zh":"乌鸦与水罐"},{"idx":14,"title_en":"The North Wind and the Sun","title_zh":"北风与太阳"},{"idx":15,"title_en":"The Hares and the Frogs","title_zh":"兔子与青蛙"},{"idx":16,"title_en":"The Fox and the Stork","title_zh":"狐狸与鹳"},{"idx":17,"title_en":"The Milkmaid and Her Pail","title_zh":"挤奶女孩与奶桶"},{"idx":18,"title_en":"The Dolphins, the Whales, and the Sprat","title_zh":"海豚、鲸与小鲱鱼"},{"idx":19,"title_en":"The Donkey and the Lapdog","title_zh":"驴与哈巴狗"},{"idx":20,"title_en":"The Gnat and the Bull","title_zh":"蚊子与公牛"},{"idx":21,"title_en":"The Bear and the Travelers","title_zh":"熊与两个旅人"},{"idx":22,"title_en":"The Oak and the Reeds","title_zh":"橡树与芦苇"},{"idx":23,"title_en":"The Donkey and His Burdens","title_zh":"驴与它的驮子"},{"idx":24,"title_en":"The Fox and the Goat","title_zh":"狐狸与山羊"},{"idx":25,"title_en":"The Boasting Traveler","title_zh":"吹牛的旅人"},{"idx":26,"title_en":"The Crab and Her Mother","title_zh":"螃蟹与蟹妈妈"},{"idx":27,"title_en":"The Donkey and His Shadow","title_zh":"驴与驴的影子"},{"idx":28,"title_en":"The Farmer and His Sons","title_zh":"农夫与他的儿子们"},{"idx":29,"title_en":"The Father and His Sons","title_zh":"父亲与儿子们"},{"idx":30,"title_en":"The Old Lion","title_zh":"老狮子"},{"idx":31,"title_en":"The Boy Bathing","title_zh":"溺水的男孩"},{"idx":32,"title_en":"The Quack Frog","title_zh":"冒牌大夫青蛙"},{"idx":33,"title_en":"Jupiter and the Tortoise","title_zh":"朱庇特与乌龟"},{"idx":34,"title_en":"The Dog in the Manger","title_zh":"占着食槽的狗"},{"idx":35,"title_en":"The Two Bags","title_zh":"两只袋子"},{"idx":36,"title_en":"The Oxen and the Axles","title_zh":"牛与车轴"},{"idx":37,"title_en":"The Boy and the Hazelnuts","title_zh":"男孩与榛子"},{"idx":38,"title_en":"The Frogs Asking for a King","title_zh":"青蛙求王"},{"idx":39,"title_en":"The Walnut Tree","title_zh":"核桃树"},{"idx":40,"title_en":"The Man and the Lion","title_zh":"人与狮子"},{"idx":41,"title_en":"The Tortoise and the Eagle","title_zh":"乌龟与鹰"},{"idx":42,"title_en":"The Young Goat on the Roof","title_zh":"屋顶上的小山羊"},{"idx":43,"title_en":"The Fox Without a Tail","title_zh":"没有尾巴的狐狸"},{"idx":44,"title_en":"The Vain Jackdaw","title_zh":"爱慕虚荣的寒鸦"},{"idx":45,"title_en":"The Fawn and His Mother","title_zh":"小鹿与母鹿"},{"idx":46,"title_en":"The Fox and the Lion","title_zh":"狐狸与狮子"},{"idx":47,"title_en":"The Stag at the Pool","title_zh":"水边的鹿"},{"idx":48,"title_en":"The Dog and His Reflection","title_zh":"狗与水中的影子"},{"idx":49,"title_en":"The Peacock and Juno","title_zh":"孔雀与朱诺"},{"idx":50,"title_en":"The Ox and the Frog","title_zh":"牛与青蛙"},{"idx":51,"title_en":"Hercules and the Wagoner","title_zh":"赫拉克勒斯与车夫"},{"idx":52,"title_en":"The Man and the Satyr","title_zh":"人与萨梯"},{"idx":53,"title_en":"The Eagle and the Arrow","title_zh":"鹰与箭"},{"idx":54,"title_en":"The Old Woman and the Wine Jar","title_zh":"老妇人与酒坛"},{"idx":55,"title_en":"The Goat and the Vine","title_zh":"山羊与葡萄藤"},{"idx":56,"title_en":"The Two Pots","title_zh":"两只罐子"},{"idx":57,"title_en":"The Old Hound","title_zh":"老猎犬"},{"idx":58,"title_en":"The Hound and the Hare","title_zh":"猎犬与野兔"},{"idx":59,"title_en":"The Wolf and the Crane","title_zh":"狼与鹳"},{"idx":60,"title_en":"The Town Mouse and the Country Mouse","title_zh":"城里老鼠与乡下老鼠"},{"idx":61,"title_en":"The Stag with One Eye","title_zh":"独眼鹿"},{"idx":62,"title_en":"The Rooster and the Jewel","title_zh":"公鸡与宝石"},{"idx":63,"title_en":"The Belly and the Members","title_zh":"肚子与四肢"},{"idx":64,"title_en":"The Bald Man and the Fly","title_zh":"秃头人与苍蝇"},{"idx":65,"title_en":"The Travelers and the Plane Tree","title_zh":"旅人与梧桐树"},{"idx":66,"title_en":"The Birds, the Beasts, and the Bat","title_zh":"鸟、兽与蝙蝠"},{"idx":67,"title_en":"The Miller, His Son, and Their Donkey","title_zh":"磨坊主、儿子与驴"},{"idx":68,"title_en":"The Stag and the Vine","title_zh":"鹿与葡萄藤"},{"idx":69,"title_en":"The Astronomer","title_zh":"天文学家"},{"idx":70,"title_en":"The Laborer and the Snake","title_zh":"雇工与蛇"},{"idx":71,"title_en":"The Young Goat and the Wolf","title_zh":"小山羊与狼"},{"idx":72,"title_en":"The Bald Huntsman","title_zh":"秃头猎人"},{"idx":73,"title_en":"The Father and His Daughters","title_zh":"父亲与两个女儿"},{"idx":74,"title_en":"The Pack Donkey and the Wild Donkey","title_zh":"驮货驴与野驴"},{"idx":75,"title_en":"The Frogs and the Well","title_zh":"青蛙与水井"},{"idx":76,"title_en":"The Shepherd and the Wolf","title_zh":"牧人与狼"},{"idx":77,"title_en":"The Rivers and the Sea","title_zh":"河流与大海"},{"idx":78,"title_en":"The Lion in Love","title_zh":"恋爱中的狮子"},{"idx":79,"title_en":"The Dog and the Wolf","title_zh":"狗与狼"},{"idx":80,"title_en":"The Swan","title_zh":"天鹅"},{"idx":81,"title_en":"The Eagle and the Fox","title_zh":"鹰与狐狸"},{"idx":82,"title_en":"The Fox and the Hedgehog","title_zh":"狐狸与刺猬"},{"idx":83,"title_en":"The Witch","title_zh":"女巫"},{"idx":84,"title_en":"The Old Man and Death","title_zh":"老人与死神"},{"idx":85,"title_en":"The Miser","title_zh":"守财奴"},{"idx":86,"title_en":"The Horse and the Stag","title_zh":"马与鹿"},{"idx":87,"title_en":"The Man Who Lost His Spade","title_zh":"丢了铲子的人"},{"idx":88,"title_en":"Prometheus and the Making of Man","title_zh":"普罗米修斯造人"},{"idx":89,"title_en":"The Traveler and Fortune","title_zh":"旅人与命运女神"}]'::jsonb, false, 'public')
