-- 2) 句子(删旧重灌,幂等)。audio_url 留 NULL:默认前端实时合成,预生成脚本审后另回填。
DELETE FROM public.library_sentences
 WHERE book_id = (SELECT id FROM public.library_books WHERE book_key = 'aesop-easy-readers');

INSERT INTO public.library_sentences (book_id, chapter_idx, para_idx, seq, text_en, text_cn)
SELECT b.id, v.chapter_idx, v.para_idx, v.seq, v.text_en, v.text_cn
FROM public.library_books b
CROSS JOIN (VALUES
    (1, 1, 1, 'A hare laughed at a tortoise.', '一只兔子嘲笑一只乌龟。'),
    (1, 1, 2, '"You are so slow!" he said.', '“你太慢了!”他说。'),
    (1, 1, 3, '"Let''s have a race," said the tortoise.', '“我们来赛跑吧,”乌龟说。'),
    (1, 1, 4, 'The hare thought this was very funny.', '兔子觉得这非常好笑。'),
    (1, 2, 5, 'The race began, and the hare ran fast.', '比赛开始了,兔子跑得飞快。'),
    (1, 2, 6, 'Soon he was far ahead.', '很快他就遥遥领先。'),
    (1, 2, 7, '"I have time to rest," he said, and fell asleep.', '“我有时间休息,”他说着就睡着了。'),
    (1, 3, 8, 'The tortoise walked on and on.', '乌龟一直不停地走。'),
    (1, 3, 9, 'He passed the sleeping hare.', '他经过了正在睡觉的兔子。'),
    (1, 3, 10, 'When the hare woke up, the tortoise had won.', '兔子醒来时,乌龟已经赢了。'),
    (1, 3, 11, 'Slow and steady wins the race.', '稳扎稳打者胜。'),
    (2, 4, 12, 'A lion was asleep in the sun.', '一只狮子在阳光下睡觉。'),
    (2, 4, 13, 'A little mouse ran over his nose.', '一只小老鼠从他的鼻子上跑过。'),
    (2, 4, 14, 'The lion woke up and caught the mouse.', '狮子醒了,抓住了老鼠。'),
    (2, 4, 15, '"Please let me go," cried the mouse.', '“请放了我吧,”老鼠喊道。'),
    (2, 4, 16, '"One day I may help you."', '“也许有一天我能帮到你。”'),
    (2, 5, 17, 'The lion laughed, but he let the mouse go.', '狮子笑了,但还是放走了老鼠。'),
    (2, 5, 18, 'Later, the lion was caught in a net.', '后来,狮子被困在了网里。'),
    (2, 5, 19, 'He roared, but he could not get free.', '他吼叫着,却挣脱不了。'),
    (2, 6, 20, 'The little mouse heard him.', '小老鼠听见了他。'),
    (2, 6, 21, 'She ran over and bit the ropes.', '她跑过来,咬断了绳子。'),
    (2, 6, 22, 'Soon the lion was free.', '很快狮子就自由了。'),
    (2, 6, 23, 'Even a small friend can be a great help.', '再小的朋友也能帮上大忙。'),
    (3, 7, 24, 'A hungry fox saw some grapes.', '一只饥饿的狐狸看见了一些葡萄。'),
    (3, 7, 25, 'They hung high on a vine.', '它们高高地挂在藤上。'),
    (3, 7, 26, '"Those grapes look sweet," he said.', '“那些葡萄看起来很甜,”他说。'),
    (3, 8, 27, 'The fox jumped up, but he missed.', '狐狸跳起来,却没够着。'),
    (3, 8, 28, 'He tried again and again.', '他一次又一次地尝试。'),
    (3, 8, 29, 'Each time, he could not reach them.', '每一次都够不到。'),
    (3, 9, 30, 'At last, the fox walked away.', '最后,狐狸走开了。'),
    (3, 9, 31, '"I don''t want them," he said.', '“我才不要它们呢,”他说。'),
    (3, 9, 32, '"They are sour anyway."', '“反正它们是酸的。”'),
    (3, 9, 33, 'It is easy to hate what you cannot have.', '得不到的东西,就容易去讨厌它。'),
    (4, 10, 34, 'In summer, an ant worked hard.', '夏天,一只蚂蚁辛勤地劳作。'),
    (4, 10, 35, 'She saved food for the winter.', '她为冬天储备食物。'),
    (4, 10, 36, 'A grasshopper sang all day.', '一只蚱蜢整天唱歌。'),
    (4, 10, 37, '"Why work so much?" he asked.', '“干嘛干这么多活?”他问。'),
    (4, 11, 38, '"Come and play with me!"', '“过来和我一起玩吧!”'),
    (4, 11, 39, '"There is plenty of food now."', '“现在食物多得很。”'),
    (4, 11, 40, 'But the ant did not stop.', '但蚂蚁没有停下。'),
    (4, 12, 41, 'Then winter came, and it was cold.', '后来冬天来了,天很冷。'),
    (4, 12, 42, 'The grasshopper had no food.', '蚱蜢没有食物。'),
    (4, 12, 43, 'The ant was warm and full.', '蚂蚁却温暖又饱足。'),
    (4, 12, 44, 'It is wise to prepare for hard days.', '未雨绸缪才是明智之举。'),
    (5, 13, 45, 'A man and his wife owned a goose that laid one golden egg a day.', '一对夫妻养着一只鹅，每天下一个金蛋。'),
    (5, 13, 46, 'For a while that seemed like the best luck anyone had ever had.', '有那么一阵子，他们觉得这是天底下最好的运气。'),
    (5, 13, 47, 'Then they started doing the math. One egg a day was a fortune, but it was a slow fortune, and they were impatient.', '后来他们开始算账。一天一个金蛋是笔财富，可这财富来得太慢，他们等不及了。'),
    (5, 13, 48, 'They convinced themselves the goose had to be solid gold inside, and that all they needed to do was open it up and take everything at once.', '他们说服自己相信：这鹅肚子里一定是实心的金子，只要剖开它，就能一次把全部拿到手。'),
    (5, 13, 49, 'So they killed it.', '于是他们把鹅杀了。'),
    (5, 13, 50, 'Inside, it was exactly like any other goose.', '里面和别的鹅没有半点区别。'),
    (5, 13, 51, 'They didn''t get rich that day, and they never got another egg either.', '那天他们没能发财，此后也再没有过一个金蛋。'),
    (6, 14, 52, 'A cat heard about a house that was overrun with mice. "That''s the place for me," she said, and moved in.', '一只猫听说有户人家闹耗子。“这地方正合我意，”她说，然后就搬了进去。'),
    (6, 14, 53, 'She caught them one by one and ate them, until the mice couldn''t take it anymore and decided to stay down in their holes for good.', '她把耗子一只只逮来吃掉，直到耗子们再也受不了，决定从此躲在洞里不出来。'),
    (6, 14, 54, 'That was inconvenient for the cat, so she came up with a trick.', '这对猫来说很不方便，于是她想了个招。'),
    (6, 14, 55, 'She climbed the wall, hooked her back legs over a peg, hung there upside down, and played dead.', '她爬上墙，用后腿勾住一根木钉，倒挂在那儿装死。'),
    (6, 14, 56, 'After a while a mouse poked its head out and saw her hanging there.', '过了一会儿，一只耗子探出头来，看见她挂在那里。'),
    (6, 14, 57, '"Very clever, ma''am," it said. "But you can hang there and turn yourself into a sack of flour for all I care. You still won''t get any of us to come near you."', '“高明，夫人，”它说，“不过您尽管挂着，挂成一袋面粉都行。我们照样一个都不会过去。”'),
    (7, 15, 58, 'There was a dog who bit people for no reason at all, and he made life miserable for anyone who came to his master''s house.', '有条狗无缘无故就咬人，凡是上他主人家来的，没一个不被他闹得心烦。'),
    (7, 15, 59, 'So his master hung a bell on his collar to warn people he was coming.', '于是主人在他脖子上挂了个铃铛，好让人听见他过来。'),
    (7, 15, 60, 'The dog was delighted with it and went strutting around the yard making it ring.', '狗得意得不行，在院子里昂首阔步，把铃铛摇得叮当响。'),
    (7, 15, 61, 'An old dog watched him for a while. "I''d give myself fewer airs if I were you," he said. "You don''t think they gave you that for good behavior, do you?"', '一条老狗看了他一会儿。“换了我，就不会这么摆谱，”他说，“你不会真以为这东西是奖给你的吧？”'),
    (8, 16, 62, 'The mice held a council to work out how to protect themselves from the cat.', '老鼠们开了个会，商量怎么防住猫。'),
    (8, 16, 63, 'Several plans were argued over and thrown out. Then a mouse with some standing got up and said he had solved it.', '好几个方案被争来争去，又都被否掉。后来一只有些资历的老鼠站起来，说他想出办法了。'),
    (8, 16, 64, '"We hang a bell around the cat''s neck. Then we hear her coming, every time."', '“我们在猫脖子上挂个铃铛。这样她一动，我们次次都听得见。”'),
    (8, 16, 65, 'The room loved it. They were about to vote it through when an old mouse stood up.', '全场叫好。眼看就要表决通过，一只年长的老鼠站了起来。'),
    (8, 16, 66, '"It''s a fine plan," he said. "I agree with all of you. May I just ask who is going to put the bell on the cat?"', '“这主意很好，”他说，“我同意各位。我只想问一句：谁去把铃铛挂到猫脖子上？”'),
    (9, 17, 67, 'A crow was sitting in a tree with a piece of cheese in her beak when a fox spotted her and started working out how to get it.', '一只乌鸦叼着一块奶酪停在树上，被一只狐狸看见了，他立刻盘算起怎么把奶酪弄到手。'),
    (9, 17, 68, 'He stood under the branch and looked up. "What a magnificent bird. There''s nothing to match her coloring. If her voice is anywhere near as fine as her looks, she ought to be queen of the birds."', '他站到树下抬头看。“多气派的一只鸟。这身羽色无人能及。要是嗓子有这副模样一半好，她当鸟中之王都不为过。”'),
    (9, 17, 69, 'The crow, flattered, opened her beak to prove she could sing and let out a caw.', '乌鸦被捧得飘飘然，张嘴要证明自己会唱，“呱”地叫了一声。'),
    (9, 17, 70, 'The cheese dropped. The fox snapped it up. "You have a voice, ma''am," he said. "What you''re short on is judgment."', '奶酪掉了下来。狐狸一口叼住。“嗓子您是有的，夫人，”他说，“缺的是判断力。”'),
    (10, 18, 71, 'A wolf found a lamb that had strayed from the flock.', '一只狼撞见一只离群的羊羔。'),
    (10, 18, 72, 'He didn''t want to kill something so helpless without an excuse, so he went looking for one.', '他不想毫无理由就杀掉这么个毫无还手之力的小东西，于是就去找个理由。'),
    (10, 18, 73, '"Last year," he said, "you insulted me."', '“去年，”他说，“你侮辱过我。”'),
    (10, 18, 74, '"That''s impossible," the lamb said. "I wasn''t born yet last year."', '“这不可能，”羊羔说，“去年我还没出生呢。”'),
    (10, 18, 75, '"Then you''ve been grazing in my pasture."', '“那你就是在我的草场上吃过草。”'),
    (10, 18, 76, '"I couldn''t have. I''ve never even tasted grass."', '“我不可能吃过。我连草是什么味道都还不知道。”'),
    (10, 18, 77, '"You''ve been drinking from my spring, then."', '“那就是喝过我的泉水。”'),
    (10, 18, 78, '"I''ve never had anything but my mother''s milk."', '“我除了母亲的奶，什么都没喝过。”'),
    (10, 18, 79, '"Well," the wolf said, "I''m not going hungry over it."', '“行吧，”狼说，“反正我不会为这个饿着肚子。”'),
    (10, 18, 80, 'He sprang on the lamb and ate it, excuse or no excuse.', '他扑上去把羊羔吃了，有没有理由都一样。'),
    (11, 19, 81, 'A man who had run through his money had nothing left but the clothes he stood in when he saw a swallow one bright morning in early spring.', '一个把钱挥霍光的人，除了身上那身衣服什么也不剩了，早春一个大晴天，他看见一只燕子。'),
    (11, 19, 82, 'He decided summer had arrived and he wouldn''t be needing his coat, so he sold it for whatever it would bring.', '他认定夏天到了，外套用不着了，就把它卖了，能卖多少算多少。'),
    (11, 19, 83, 'The weather turned. A hard frost came, and the swallow died of it.', '天说变就变。一场硬霜下来，那只燕子冻死了。'),
    (11, 19, 84, 'When the man found the bird lying dead, he said, "You wretched thing. Because of you I''m freezing to death myself."', '他看见那只鸟死在地上，说：“你这倒霉东西。就为了你，我自己也要冻死了。”'),
    (12, 20, 85, 'A woodman was cutting down a tree by a river when his ax glanced off the trunk, flew out of his hands, and went into the water.', '一个樵夫在河边砍树，斧子从树干上滑开，脱手飞了出去，掉进了水里。'),
    (12, 20, 86, 'He was standing at the edge of the river, miserable, when Mercury appeared and asked what was wrong.', '他站在河边发愁，这时墨丘利现身，问他出了什么事。'),
    (12, 20, 87, 'When he heard the story, Mercury felt sorry for him, dove in, and came up holding a golden ax. Was this the one?', '听完之后，墨丘利动了恻隐之心，潜下水去，捞上来一把金斧子。是这把吗？'),
    (12, 20, 88, 'The woodman said it wasn''t.', '樵夫说不是。'),
    (12, 20, 89, 'Mercury dove again and surfaced with a silver ax. This one?', '墨丘利又潜下去，捞上来一把银斧子。这把呢？'),
    (12, 20, 90, '"No, that''s not mine either."', '“不是，这把也不是我的。”'),
    (12, 20, 91, 'The third time, Mercury brought up the ax he had actually lost. The woodman thanked him over and over, and Mercury, impressed by his honesty, gave him the other two axes as well.', '第三次，墨丘利捞上来的正是他丢的那把。樵夫千恩万谢，墨丘利被他的诚实打动，把另外两把斧子也一并送给了他。'),
    (12, 20, 92, 'When the woodman told his friends what had happened, one of them couldn''t stand it and decided to try the same thing himself.', '樵夫把这事讲给同伴听，其中一个眼红得受不了，决定自己也去试一回。'),
    (12, 20, 93, 'He went down to the river, started cutting at a tree, and managed to let his ax fall in.', '他跑到河边，装模作样砍起树来，想法子让斧子掉进了水里。'),
    (12, 20, 94, 'Mercury appeared just as before, heard what had happened, dove, and came up with a golden ax.', '墨丘利像上次一样出现，问明缘由，潜下水去，捞上来一把金斧子。'),
    (12, 20, 95, 'The man didn''t wait to be asked. "That''s mine, that''s mine," he said, reaching for it.', '那人没等发问就伸手去够：“那是我的，那是我的。”'),
    (12, 20, 96, 'Mercury was disgusted enough that he not only kept the golden ax, he left the man''s own ax at the bottom of the river.', '墨丘利厌恶到不但没把金斧子给他，连他自己那把也没替他捞上来。'),
    (13, 21, 97, 'A thirsty crow found a pitcher with water at the bottom of it, but there was so little that no matter how she angled her beak she couldn''t reach it.', '一只口渴的乌鸦找到一只罐子，底上还剩一点水，可实在太少，她的嘴怎么伸都够不着。'),
    (13, 21, 98, 'For a while it looked like she would die of thirst with the water right in front of her.', '有那么一阵，眼看她就要在水跟前活活渴死。'),
    (13, 21, 99, 'Then she started dropping pebbles into the pitcher, one after another, and with every pebble the water climbed a little higher, until it came up far enough for her to drink.', '后来她开始往罐子里丢石子，一颗接一颗，每丢一颗水就往上涨一点，直到涨得够高，她终于喝上了。'),
    (14, 22, 100, 'The north wind and the sun got into an argument about which of them was stronger.', '北风和太阳争了起来，都说自己更厉害。'),
    (14, 22, 101, 'Neither would back down, so they agreed on a test: a traveler was coming up the road in a heavy cloak, and whoever got it off him would win.', '谁也不肯让步，于是他们定下一场比试：路上正走来一个裹着厚斗篷的旅人，谁能让他把斗篷脱下来，谁就赢。'),
    (14, 22, 102, 'The wind went first.', '北风先来。'),
    (14, 22, 103, 'He gathered all his force and came roaring down on the man, tearing at the cloak as if he could rip it away in one pull.', '他鼓足全身力气朝那人猛扑下去，撕扯着那件斗篷，像是要一把将它扯走。'),
    (14, 22, 104, 'But the harder he blew, the tighter the man wrapped it around himself.', '可他刮得越狠，那人把斗篷裹得越紧。'),
    (14, 22, 105, 'When the wind had worn himself out, the sun took his turn.', '等北风把力气耗光了，轮到太阳。'),
    (14, 22, 106, 'He started gently, just warming the road, and before long the traveler unfastened the cloak and let it hang loose off his shoulders.', '太阳先是不紧不慢地晒着，把路面烘暖，没过多久，旅人就解开斗篷，任它松松垮垮地搭在肩上。'),
    (14, 22, 107, 'Then he shone with everything he had, and within a few steps the man pulled the cloak off completely and walked on, glad to be rid of it.', '接着太阳使出全力，那人没走几步就把斗篷整个脱了下来，如释重负地继续赶路。'),
    (14, 22, 108, 'The wind had spent all afternoon on something the sun did without raising his voice.', '北风折腾了一下午的事，太阳连嗓门都没抬一下就办成了。'),
    (15, 23, 109, 'The hares got together and talked about how miserable their lives were. They were in danger from every direction and had neither the strength nor the nerve to do anything about it.', '兔子们聚到一起，说起自己的日子有多苦。四面八方都是危险，而它们既没有力气也没有胆子去应付。'),
    (15, 23, 110, 'Men, dogs, birds, and every predator alive hunted them and ate them, day after day.', '人、狗、鸟，还有一切食肉的东西，天天都在追它们、吃它们。'),
    (15, 23, 111, 'Rather than go on like that, they agreed as a group to end it, and the whole crowd of them ran for a nearby pool to drown themselves.', '与其这样过下去，它们一致决定了断了自己，于是一大群一起朝附近一个水塘冲了过去。'),
    (15, 23, 112, 'There were frogs sitting on the bank, and when they heard the hares coming they went into the water together and hid in the deep part.', '塘边坐着一些青蛙，听见兔子跑过来的动静，齐刷刷跳进水里，躲进了深处。'),
    (15, 23, 113, 'One of the older hares stopped. "Wait," he called. "There are creatures here that are frightened of us. Whatever we are, they have it worse."', '一只年长的兔子停住了。“慢着，”他喊道，“这儿还有怕我们的东西呢。我们再不济，也还有比我们更难的。”'),
    (16, 24, 114, 'A fox invited a stork to dinner and served nothing but soup, in a wide, flat dish.', '狐狸请鹳吃饭，只上了一道汤，盛在一只又宽又平的浅盘里。'),
    (16, 24, 115, 'He lapped it up happily. The stork, with her long bill, couldn''t get at any of it, and the fox found her struggling very funny.', '他吃得津津有味。鹳那张长喙什么也够不着，狐狸看着她干着急，觉得很好笑。'),
    (16, 24, 116, 'Not long after, the stork invited him back. She set out a pitcher with a long, narrow neck, which her bill slid into without any trouble.', '没过多久，鹳回请了他。她端出一只细长颈的瓶子，她的喙伸进去毫不费力。'),
    (16, 24, 117, 'She ate well. The fox sat next to her the whole time, hungry, with the food in plain sight and no way to reach it.', '她吃得很好。狐狸在旁边坐了一整顿，饿着肚子，饭菜就在眼前，一口也够不着。'),
    (17, 25, 118, 'A farmer''s daughter was walking back from milking the cows with the pail balanced on her head, and she let her mind wander.', '农夫的女儿挤完牛奶往回走，奶桶顶在头上，她的心思飘了起来。'),
    (17, 25, 119, 'The milk in the pail would give her cream, and she would churn the cream into butter and sell the butter at market.', '桶里的奶能撇出奶油，奶油搅成黄油，黄油拿到集市上卖掉。'),
    (17, 25, 120, 'With that money she would buy eggs, and the eggs would hatch into chickens, and before long she would have a whole yard full of birds.', '卖来的钱买鸡蛋，鸡蛋孵出小鸡，用不了多久她就能有满满一院子的鸡。'),
    (17, 25, 121, 'She would sell some of them, and with what they brought in she would buy herself a new dress to wear to the fair.', '卖掉一些，用换来的钱给自己做一条新裙子，赶集的时候穿。'),
    (17, 25, 122, 'Every young man there would notice it, and she would toss her head and not give any of them a word.', '那儿的年轻人个个都会注意到，而她只把头一扬，一个字也不给他们。'),
    (17, 25, 123, 'She tossed her head.', '她把头一扬。'),
    (17, 25, 124, 'The pail came down, the milk went into the road, and the butter and the chickens and the dress went with it.', '桶掉了下来，奶洒了一路，黄油、小鸡和新裙子也跟着一起没了。'),
    (18, 26, 125, 'The dolphins and the whales fell out, and before long they were fighting.', '海豚和鲸闹翻了，没过多久就打了起来。'),
    (18, 26, 126, 'The battle was vicious and went on a long time with no sign of ending.', '那一仗打得凶，打了很久也不见有个头。'),
    (18, 26, 127, 'A sprat decided he might be able to stop it, so he swam in between them and started making the case for peace.', '一条小鲱鱼觉得自己也许能劝住，就游到两边中间，开始讲和。'),
    (18, 26, 128, 'One of the dolphins looked at him. "We''d sooner fight until every one of us is dead than be talked out of it by a sprat."', '一只海豚看了他一眼。“我们宁可打到一个不剩，也不要被你这么条小鲱鱼劝下来。”'),
    (19, 27, 129, 'A man kept a donkey and a lapdog.', '有个人养着一头驴和一条哈巴狗。'),
    (19, 27, 130, 'The donkey had a stall, plenty of hay and oats, and about as good a life as a donkey could ask for.', '驴有自己的棚，草料和燕麦都不缺，日子过得算是驴里头顶好的了。'),
    (19, 27, 131, 'The little dog was the master''s pet. He was fussed over, allowed to lie in his lap, and whenever the man came home from dinner somewhere he brought back a scrap or two for the dog, who ran to meet him at the door.', '那条小狗是主人的心头肉。主人成天逗它、抱它，让它趴在腿上；每回在外头吃完饭回来，都要给跑到门口迎他的它带上一两口好的。'),
    (19, 27, 132, 'The donkey worked. He hauled loads, turned the mill, carried whatever the farm needed carrying, and after a while he could not stop comparing his own days with the dog''s.', '驴要干活。驮东西、拉磨、田里要运什么就运什么，日子一久，他忍不住总拿自己的日子和那条狗的比。'),
    (19, 27, 133, 'One day he broke his halter and came trotting into the house just as his master was sitting down to eat.', '有一天他挣断缰绳，一路小跑冲进屋，正赶上主人坐下吃饭。'),
    (19, 27, 134, 'He pranced around the room doing his best imitation of the dog, knocked over the table, and smashed the dishes.', '他在屋里连蹦带跳，学着狗的样子撒欢，掀翻了桌子，砸碎了一地碗盘。'),
    (19, 27, 135, 'Then he tried to climb into his master''s lap, the way he had watched the dog do a hundred times.', '接着他想爬到主人腿上去，就像他看那条狗做过上百回那样。'),
    (19, 27, 136, 'The servants saw their master about to be crushed and went at the donkey with sticks and clubs, and beat him back out to the stable half dead.', '仆人们眼看主人要被压着，抄起棍棒朝驴身上招呼，把他打得半死赶回棚里。'),
    (19, 27, 137, '"I had honest work and a stall of my own," he said. "I wanted to be the lapdog instead."', '“我有正经活干，有自己的棚，”他说，“我却偏想去当那条哈巴狗。”'),
    (20, 28, 138, 'A gnat landed on one of a bull''s horns and sat there for a good long while.', '一只蚊子落在公牛的一只角上，稳稳当当停了好一阵。'),
    (20, 28, 139, 'When it had rested enough and was ready to leave, it said, "Do you mind if I go now?"', '歇够了，正要走，它说：“我这就走，你不介意吧？”'),
    (20, 28, 140, 'The bull barely lifted his eyes. "Makes no difference to me. I didn''t notice you land, and I won''t notice you leave."', '公牛眼皮都懒得抬。“对我没什么两样。你落下来我没察觉，你飞走我也不会知道。”'),
    (21, 29, 141, 'Two travelers were on the road together when a bear came out ahead of them.', '两个旅人结伴赶路，一头熊迎面从前头冒了出来。'),
    (21, 29, 142, 'Before it saw them, one of them scrambled up a tree by the road and hid in the branches.', '熊还没看见他们，其中一个就爬上路边一棵树，躲进了枝叶里。'),
    (21, 29, 143, 'The other wasn''t quick enough and couldn''t get away, so he dropped to the ground and played dead, because a bear, they say, won''t touch a body.', '另一个没那么利索，逃不掉，索性趴到地上装死，据说熊是不碰死人的。'),
    (21, 29, 144, 'The bear came over and sniffed him all over, and he held his breath and didn''t move. It took him for a corpse and left.', '熊过来把他从头到脚闻了个遍，他屏着气一动不动。熊当他死了，走了。'),
    (21, 29, 145, 'When it was safe, the man in the tree climbed down and asked, half joking, what the bear had whispered in his ear.', '危险过去，树上那个爬下来，半开玩笑地问：熊凑到你耳边说了什么悄悄话？'),
    (21, 29, 146, '"He told me not to travel with a friend who leaves you the moment things get dangerous."', '“他叫我别跟一遇险就撇下你的朋友一块儿上路。”'),
    (22, 30, 147, 'An oak growing on a riverbank was torn out by a gale and thrown across the water.', '一棵长在河岸上的橡树被一场大风连根拔起，横倒在水面上。'),
    (22, 30, 148, 'It landed among the reeds. "How did you manage it?" the oak said. "You''re thin and frail, and the storm left you standing. I had all my strength and it pulled me out by the roots."', '它落进了一丛芦苇里。“你们是怎么挺过来的？”橡树说，“又细又弱，风过去了还站着。我这一身力气，却被连根拔起。”'),
    (22, 30, 149, '"You fought it," the reeds answered. "We bend for every breeze that comes along, and the storm went over our heads."', '“你跟它硬扛，”芦苇答道，“我们来一阵风就弯一次腰，那场大风就从我们头顶上过去了。”'),
    (23, 31, 150, 'A peddler bought a load of salt and piled as much of it on his donkey as the animal could carry.', '一个小贩买了一批盐，能往驴背上堆多少就堆多少。'),
    (23, 31, 151, 'On the way home the donkey slipped crossing a stream and went down in the water. The salt soaked through and most of it dissolved and washed away, so when he got back on his feet his load was much lighter.', '回家路上过溪，驴一脚踩滑摔进水里。盐泡透了，大半化掉冲走，等他重新站起来，背上轻了不少。'),
    (23, 31, 152, 'His owner turned around, went back to town, bought more salt, added it to what was left in the packs, and set out again.', '主人掉头回城，又买了盐，添在剩下的驮子里，再次上路。'),
    (23, 31, 153, 'The moment they reached the stream, the donkey lay down in it. He got up light again.', '一到溪边，驴当即躺了下去。起来时又轻了。'),
    (23, 31, 154, 'His owner had figured out the trick by then. He went into town one more time and bought a large quantity of sponges, and loaded those on instead.', '主人这回看明白了。他再跑一趟城里，买了一大堆海绵，改驮海绵。'),
    (23, 31, 155, 'At the stream the donkey lay down as usual, the sponges drank up the water, and he got up carrying more than he ever had.', '到了溪边，驴照例躺下，海绵把水吸了个饱，他站起来时背上的分量比哪一回都重。'),
    (24, 32, 156, 'A fox fell into a well and couldn''t get back out.', '一只狐狸掉进井里，爬不上来。'),
    (24, 32, 157, 'A thirsty goat came along, saw him down there, and asked if the water was any good.', '一只口渴的山羊路过，看见他在下面，就问那水好不好。'),
    (24, 32, 158, '"Good? It''s the best I''ve ever tasted," the fox said. "Come down and try it."', '“好？我这辈子没喝过更好的，”狐狸说，“下来尝尝。”'),
    (24, 32, 159, 'The goat, thinking about nothing but his thirst, jumped straight in. When he''d drunk his fill he looked around for a way out, the same as the fox, and there wasn''t one.', '山羊满脑子只有解渴，一头就跳了进去。喝够了，他也像狐狸那样四下找出路，一个也没有。'),
    (24, 32, 160, '"Here''s an idea," the fox said. "Get up on your hind legs and brace your front ones against the wall. I climb up your back and over your horns and out. Then I pull you up after me."', '“我有个办法，”狐狸说，“你用后腿站起来，前腿撑住井壁。我踩着你的背、蹬着你的角上去。上去了，再把你拉上来。”'),
    (24, 32, 161, 'The goat did as he was told, and the fox went up his back and out of the well, and then walked off.', '山羊照办了，狐狸顺着他的背爬出井口，然后扬长而去。'),
    (24, 32, 162, 'The goat shouted after him about his promise.', '山羊冲着他的背影大喊，说好的拉他上来呢。'),
    (24, 32, 163, 'The fox turned around. "If your head held as much sense as your chin holds beard, you''d have checked how to get out before you got in."', '狐狸回过头。“你脑袋里但凡有你下巴上胡子那么多的脑子，下去之前就该先弄清怎么上来。”'),
    (25, 33, 164, 'A man came home from traveling abroad with a stack of impressive stories about the things he''d done.', '一个人出国游历回来，带回一大堆讲自己壮举的漂亮故事。'),
    (25, 33, 165, 'One of them was about a jumping contest on Rhodes, where he''d made a leap that nobody there could match. "Go to Rhodes and ask," he said. "Anyone will tell you."', '其中一个是说在罗得岛的跳远比赛上，他跳出了当地没人能比的一跳。“不信你去罗得岛问，”他说，“随便谁都会告诉你。”'),
    (25, 33, 166, '"If you can jump like that, we don''t need Rhodes," one of the listeners said. "Say this is Rhodes. Jump."', '“你要真能跳成那样，用不着罗得岛，”一个听的人说，“就当这儿是罗得岛。跳吧。”'),
    (26, 34, 167, 'An old crab said to her son, "Why do you walk sideways like that? You should walk straight."', '一只老螃蟹对儿子说：“你为什么老这么横着走？该直着走才对。”'),
    (26, 34, 168, '"Show me how, mother," the young crab said, "and I''ll do it your way."', '“妈妈，你走给我看，”小螃蟹说，“你怎么走我就怎么走。”'),
    (26, 34, 169, 'She tried, and tried again, and couldn''t do it either.', '她试了一回，又试一回，自己也做不到。'),
    (27, 35, 170, 'A man hired a donkey for a trip in the middle of summer, and the owner walked behind to drive it.', '有人在盛夏雇了一头驴赶路，驴的主人跟在后面赶牲口。'),
    (27, 35, 171, 'In the heat of the afternoon they stopped to rest, and the traveler lay down in the donkey''s shadow.', '午后最热的时候两人停下歇脚，那位赶路人躺进了驴的影子里。'),
    (27, 35, 172, 'The owner wanted the shade himself and told him to move. He had rented out the donkey, he said, not the donkey''s shadow.', '主人自己也想遮阴，叫他挪开。他说他租出去的是驴，不是驴的影子。'),
    (27, 35, 173, 'The traveler said that paying for the animal meant the animal was his for the day, all of it.', '赶路人说，钱既然付了，这一天里这头驴连同它的一切都归他。'),
    (27, 35, 174, 'The argument turned into a fight, and while the two of them were busy hitting each other the donkey walked off and was gone.', '争着争着就动了手，两人打得不可开交，那头驴自己走掉了，再也没影。'),
    (28, 36, 175, 'A farmer near the end of his life called his sons around him. There was something they needed to know.', '一个农夫快不行了，把儿子们叫到跟前。有件事他们得知道。'),
    (28, 36, 176, '"I''m going to die soon," he said. "There''s treasure buried in the vineyard. Dig, and you''ll find it."', '“我没几天了，”他说，“葡萄园里埋着财宝。去挖，挖得到。”'),
    (28, 36, 177, 'As soon as he was gone they took spades and forks to the vineyard and turned the soil over, and then turned it over again, and found nothing.', '他一咽气，儿子们就扛着锹和叉去了葡萄园，把土翻了一遍，又翻了一遍，什么也没挖着。'),
    (28, 36, 178, 'The vines, worked that thoroughly, produced a crop bigger than anything the family had ever seen.', '那些葡萄藤被这么彻底地翻过土，那年结出的果子比这家人见过的哪一年都多。'),
    (29, 37, 179, 'A man had several sons who fought constantly, and nothing he said made any difference.', '有个人的几个儿子成天吵架，他怎么说都不管用。'),
    (29, 37, 180, 'So he had them bring him a bundle of sticks, and he handed it to each of them in turn and told them to break it over their knee.', '于是他让他们抱来一捆柴，一个个递过去，叫他们拿膝盖把它折断。'),
    (29, 37, 181, 'Every one of them tried. None of them could.', '人人都试了。谁也折不断。'),
    (29, 37, 182, 'Then he untied the bundle and passed the sticks around one at a time, and they snapped them without any effort at all.', '接着他解开捆绳，把柴一根根分下去，他们不费吹灰之力就都折断了。'),
    (29, 37, 183, '"There," he said. "Together you''re more than anyone who comes at you can handle. Split up and you''re a pile of loose sticks."', '“看见没，”他说，“捆在一起，谁来了都拿你们没办法。散开，你们就是一堆松柴。”'),
    (30, 38, 184, 'A lion too old to hunt by force decided to hunt by cunning instead.', '一头狮子老得没法再靠力气捕猎，就改用心计。'),
    (30, 38, 185, 'He went into a cave, lay down, and pretended to be sick. Whenever an animal came in to ask how he was, he pounced on it and ate it.', '他躲进一个山洞，躺下装病。哪只动物进来探望，他就扑上去吃掉。'),
    (30, 38, 186, 'A lot of them died that way, until a fox came by. Suspecting something, he stayed outside and called in to ask how the lion was doing.', '不少动物就这么送了命，直到一只狐狸来了。他起了疑，站在洞外，冲里头问狮子近来如何。'),
    (30, 38, 187, '"Not well at all," the lion said. "But why are you standing out there? Come in."', '“很不好，”狮子说，“可你站在外头干什么？进来呀。”'),
    (30, 38, 188, '"I would have," the fox said, "except that every footprint I see points into the cave, and not one points back out."', '“我本来会进去，”狐狸说，“可我看这些脚印，全都朝洞里去，没有一个是出来的。”'),
    (31, 39, 189, 'A boy swimming in a river got out past his depth and was close to drowning.', '一个男孩在河里游泳，游到了没顶的深处，眼看要淹死。'),
    (31, 39, 190, 'A man going by on the road heard him calling for help, came to the bank, and started lecturing him about how careless it was to swim out that far, without doing anything to pull him out.', '一个从路上经过的人听见他呼救，走到岸边，开始教训他游那么远有多不小心，却没伸手拉他一把。'),
    (31, 39, 191, '"Sir," the boy called, "help me out now and scold me after."', '“先生，”男孩喊，“先把我拉上来，再骂也不迟。”'),
    (32, 40, 192, 'A frog came up out of the marsh and announced to everyone that he was a trained physician who knew his drugs and could cure any illness there was.', '一只青蛙从沼泽里爬出来，向众人宣布：他是受过训练的大夫，通晓药理，什么病都治得好。'),
    (32, 40, 193, 'A fox in the crowd called out, "You, a doctor? You can''t even fix your own limp, or that blotchy, wrinkled skin of yours."', '人群里一只狐狸喊道：“你，当大夫？你连自己那条瘸腿都治不好，还有你那身又花又皱的皮。”'),
    (33, 41, 194, 'Jupiter was getting married and invited every animal to the wedding feast.', '朱庇特要成婚，把所有动物都请去赴婚宴。'),
    (33, 41, 195, 'They all came except the tortoise, who never showed up, which surprised Jupiter.', '动物全来了，只有乌龟没到，朱庇特很意外。'),
    (33, 41, 196, 'Next time he saw him, he asked why he''d missed the feast.', '下回见到乌龟，他问他为什么没来。'),
    (33, 41, 197, '"I don''t like going out," the tortoise said. "There''s no place like home."', '“我不爱出门，”乌龟说，“哪儿都不如家里好。”'),
    (33, 41, 198, 'The answer annoyed Jupiter enough that he ruled the tortoise would carry his house on his back from then on, and never be away from home again, even if he wanted to.', '这话把朱庇特惹恼了，他当即判定：从今往后乌龟得把家背在身上，再想离开家也离不成。'),
    (34, 42, 199, 'A dog had settled down in a manger, on the hay that had been put there for the cattle.', '一条狗趴在食槽里，占着给牛准备的干草。'),
    (34, 42, 200, 'When they came to eat he growled and snapped and wouldn''t let them near it.', '牛来吃草，他又是低吼又是龇牙，不让它们靠近。'),
    (34, 42, 201, '"What a selfish animal," one of them said. "He can''t eat the hay himself, and he won''t let anyone eat it who can."', '“这畜生真自私，”其中一头牛说，“干草他自己又吃不了，能吃的他还不让吃。”'),
    (35, 43, 202, 'Everyone walks around with two bags, one hanging in front and one hanging behind, and both of them are packed full of faults.', '每个人身上都挂着两只袋子，一只在胸前，一只在背后，两只都塞满了毛病。'),
    (35, 43, 203, 'The bag in front holds everyone else''s. The one behind holds his own.', '前面那只装的是别人的，后面那只装的是自己的。'),
    (35, 43, 204, 'That is why a man can go his whole life without noticing a single fault of his own and never miss one of yours.', '所以一个人可以活一辈子看不见自己的一处毛病，却一次也不会漏掉你的。'),
    (36, 44, 205, 'A pair of oxen were hauling a heavily loaded wagon down the road, and as they pulled and strained against the yoke the axles under it creaked and groaned something awful.', '两头牛拉着一辆装得满满的车走在路上，它们顶着轭又拉又拽，车下的轴吱吱嘎嘎叫得没完。'),
    (36, 44, 206, 'The oxen had had enough. They turned around. "Hey. Why are you two making all that noise, when we''re the ones doing the work?"', '牛受够了，回过头去。“喂。活是我们干的，你们俩在那儿鬼叫什么？”'),
    (37, 45, 207, 'A boy reached into a jar of hazelnuts and grabbed as many as his fist could possibly hold.', '一个男孩把手伸进装榛子的罐子里，一把攥住了拳头能握下的最多的量。'),
    (37, 45, 208, 'When he tried to pull his hand back out, it wouldn''t come. The neck of the jar was too narrow for a fist that size.', '等他要把手抽出来，抽不动了。罐口太窄，容不下攥这么满的拳头。'),
    (37, 45, 209, 'He wouldn''t let go of the nuts and he couldn''t get his hand free, so he started crying.', '榛子他舍不得松，手又拔不出来，他就哭了起来。'),
    (37, 45, 210, 'Someone standing nearby saw where the trouble was. "Take half," he said. "Your hand will come right out."', '旁边有人看出了症结。“抓一半，”他说，“手马上就出来了。”'),
    (38, 46, 211, 'The frogs were unhappy because they had nobody ruling over them, so they sent a delegation to Jupiter to ask for a king.', '青蛙们不满意，因为头上没个管事的，就派了代表去见朱庇特，讨一个王。'),
    (38, 46, 212, 'Jupiter thought the request was ridiculous. He dropped a log into their pool and told them that was their king.', '朱庇特觉得这要求可笑。他往它们的池子里丢下一根木头，说这就是你们的王。'),
    (38, 46, 213, 'The splash scared them into the deepest part of the water. But the log didn''t move, and one by one they came back up, and once they got bold enough they took to sitting on it.', '那一声水响把它们吓进了池底。可木头一动不动，它们一只只又浮了上来，胆子壮了以后，索性坐到了木头上。'),
    (38, 46, 214, 'A king like that, they decided, was an insult. They sent to Jupiter again and asked him to take the lazy one back and give them a better one.', '它们认定这样的王是种羞辱，于是第二次派人去朱庇特那里，请他把这个懒东西收回去，换个像样的来。'),
    (38, 46, 215, 'Jupiter, tired of being pestered, sent them a stork.', '朱庇特被缠得不耐烦，给它们送去一只鹳。'),
    (38, 46, 216, 'The stork arrived and began eating frogs as fast as he could catch them.', '鹳一到，就开始逮青蛙吃，逮得有多快就吃得有多快。'),
    (39, 47, 217, 'A walnut tree by the side of the road produced a heavy crop of nuts every year.', '路边一棵核桃树，年年结出满树的核桃。'),
    (39, 47, 218, 'Everyone who passed threw sticks and stones up into its branches to knock the nuts down, and the tree took a beating for it.', '过路的人个个往它枝头扔石头、抡棍子，好把核桃打下来，那树为此没少挨打。'),
    (39, 47, 219, '"The very people who eat my nuts," it said, "are the ones who pay me back in sticks and stones."', '“吃我核桃的，”那树说，“偏偏就是拿石头棍子回报我的。”'),
    (40, 48, 220, 'A man and a lion were traveling together, and somewhere along the way the conversation turned into an argument about which of them was stronger and braver.', '一个人和一头狮子结伴赶路，走着走着，话头变成了争执：到底谁更强、谁更有胆。'),
    (40, 48, 221, 'They were still at it when they reached a crossroads with a statue of a man strangling a lion.', '两个还在争，就走到了一个岔路口，那里立着一座石像，一个人正掐着一头狮子。'),
    (40, 48, 222, '"There," the man said. "That settles which of us is stronger."', '“你看，”那人说，“谁更强，这不就清楚了。”'),
    (40, 48, 223, '"That''s your side of it," the lion said. "If lions carved statues, you''d find the man on the bottom in most of them."', '“那是你们那边的说法，”狮子说，“要是狮子会刻像，多半你会看见人在下面。”'),
    (41, 49, 224, 'A tortoise, unhappy with life on the ground and envious of the birds he watched playing in the air, begged an eagle to teach him to fly.', '一只乌龟嫌地上的日子无趣，眼馋那些在空中嬉戏的鸟，缠着一只鹰教他飞。'),
    (41, 49, 225, 'The eagle told him it was pointless. Nature hadn''t given him wings.', '鹰跟他说这没用。老天没给他翅膀。'),
    (41, 49, 226, 'But the tortoise kept at him, with pleading and promises of treasure, sure that flying was just a knack you could learn.', '可乌龟不依不饶，又是恳求又是许以财宝，一口咬定飞不过是门学得会的窍门。'),
    (41, 49, 227, 'In the end the eagle gave in, took him up in his talons, carried him high into the sky, and let go.', '鹰终究松了口，用爪子抓起他，带上高空，一撒手。'),
    (41, 49, 228, 'The tortoise dropped straight down and smashed to pieces on a rock.', '乌龟直直坠下，在一块岩石上摔得粉碎。'),
    (42, 50, 229, 'A young goat climbed onto the roof of a shed, drawn up by the grass and weeds growing in the thatch.', '一只小山羊爬上了棚顶，被茅草里长出来的青草和野草引了上去。'),
    (42, 50, 230, 'While he stood up there eating, he saw a wolf go by below and started taunting him for not being able to reach him.', '他站在上面啃着，看见一只狼从下面走过，就冲他起哄，笑他够不着自己。'),
    (42, 50, 231, 'The wolf looked up. "I hear you," he said. "But that isn''t you talking. That''s the roof."', '狼抬头看了一眼。“我听见了，”他说，“不过那不是你在说话，是那屋顶。”'),
    (43, 51, 232, 'A fox got caught in a trap and pulled himself free, but left his tail behind.', '一只狐狸掉进了捕兽夹，挣脱出来，尾巴却留在了里面。'),
    (43, 51, 233, 'He was embarrassed enough that he decided life would be unbearable unless he could talk the other foxes into cutting off theirs too, so that nobody would be looking at his.', '他难堪得厉害，觉得日子没法过了，除非能说动别的狐狸也把尾巴剪掉，好让谁都不再盯着他看。'),
    (43, 51, 234, 'He called a meeting and made his case. "They''re ugly," he said. "They''re heavy. You spend your whole life dragging one around behind you for nothing."', '他召集大家开了个会，把道理讲了一遍。“尾巴难看，”他说，“又沉。一辈子在身后拖着这么个玩意儿，图什么？”'),
    (43, 51, 235, '"My friend," another fox said, "if you still had yours, you wouldn''t be half so eager for us to lose ours."', '“朋友，”另一只狐狸说，“要是你自己那条还在，你哪会这么起劲让我们剪掉。”'),
    (44, 52, 236, 'Jupiter announced he was going to appoint a king over the birds, and set a day for them to appear before his throne, where he would pick the most beautiful of them to rule.', '朱庇特宣布要给鸟类立一个王，定下日子让它们到他的宝座前齐集，届时他从中挑最美的那只来当王。'),
    (44, 52, 237, 'Wanting to look their best, the birds went down to a stream to wash and preen.', '为了在那天最漂亮地亮相，鸟儿们都跑到一条溪边梳洗、整理羽毛。'),
    (44, 52, 238, 'The jackdaw was there too, and he knew that with his own drab feathers he had no chance.', '寒鸦也在其中，他清楚凭自己那身灰扑扑的羽毛，一点指望也没有。'),
    (44, 52, 239, 'So he waited until the others had gone, gathered up the brightest feathers they had dropped, and fixed them all over himself, until he looked more brilliant than any of them.', '于是他等旁的鸟都走了，把它们掉下的最鲜亮的羽毛捡起来，一根根插满自己全身，弄得比谁都光彩夺目。'),
    (44, 52, 240, 'On the day, the birds gathered at the throne. Jupiter looked them over and was about to make the jackdaw king when the rest of them fell on him, tore off every borrowed feather, and left him standing there as the jackdaw he was.', '到了那天，鸟儿们在宝座前聚齐。朱庇特一一看过去，正要立寒鸦为王，别的鸟一拥而上，把借来的羽毛一根不剩地拔了下来，让他露出寒鸦的本相立在那儿。'),
    (45, 53, 241, 'A doe said to her fawn, who was fully grown now and strong, "Nature gave you a big body and a good pair of horns. I don''t understand why you run from the hounds."', '一只母鹿对已经长大长壮的小鹿说：“老天给了你结实的身板和一对好角。我真不明白你为什么见了猎狗就跑。”'),
    (45, 53, 242, 'Right then they both heard a pack in full cry, still some distance off.', '正说着，两只鹿都听见远处传来一群猎狗的吠声。'),
    (45, 53, 243, '"You stay where you are," she said. "Don''t worry about me."', '“你待着别动，”她说，“别管我。”'),
    (45, 53, 244, 'And she was gone, running as fast as her legs would take her.', '说完她撒开腿就跑，跑得要多快有多快。'),
    (46, 54, 245, 'A fox who had never seen a lion came across one, and the sight of him left the fox nearly dead with fright.', '一只从没见过狮子的狐狸撞见了一头狮子，那模样吓得他差点没了命。'),
    (46, 54, 246, 'The second time he met him he was still afraid, but nothing like before.', '第二次碰见，他还是怕，可远不像头一回那么怕了。'),
    (46, 54, 247, 'The third time, he walked right up and struck up a conversation as if they''d known each other for years.', '到第三次，他径直走上前去搭话，像是相识多年的老熟人。'),
    (47, 55, 248, 'A thirsty stag went down to a pool to drink, and as he bent over the water he saw his reflection.', '一头口渴的鹿下到水塘边喝水，俯身时看见了自己水中的影子。'),
    (47, 55, 249, 'He admired his wide, branching antlers, and in the same breath felt nothing but disgust for his thin, spindly legs.', '他欣赏自己那对宽大分叉的鹿角，转念又对自己那双又细又瘦的腿满是嫌弃。'),
    (47, 55, 250, 'While he stood there studying himself, a lion spotted him and charged.', '他正站在那儿端详自己，一头狮子瞅见了他，扑了过来。'),
    (47, 55, 251, 'The stag ran, and as long as the ground was open he pulled well ahead. But when he reached a wood, his antlers caught in the branches, and the lion was on him.', '鹿撒腿就跑，只要是空地，他就把狮子远远甩在后头。可一跑进树林，鹿角便卡在枝桠上，狮子追了上来。'),
    (47, 55, 252, 'The legs he''d been ashamed of would have carried him clear. The antlers he''d been proud of were what held him for the lion.', '他嫌弃的那双腿本可以带他脱身。他引以为傲的那对角，却把他按在原地留给了狮子。'),
    (48, 56, 253, 'A dog was crossing a plank bridge over a stream with a piece of meat in his mouth when he caught sight of his own reflection in the water.', '一条狗嘴里叼着一块肉，正走过溪上的木板桥，忽然看见自己在水里的影子。'),
    (48, 56, 254, 'He took it for another dog carrying a piece twice the size of his, so he dropped his own and lunged for the better one.', '他把那当成了另一条狗，叼的那块比自己的大一倍，于是松开嘴，扑过去抢那块更好的。'),
    (48, 56, 255, 'He came up with nothing. One piece had never existed, and the other was already going downstream.', '他什么也没捞着。一块从来就不存在，另一块已经顺水漂走了。'),
    (49, 57, 256, 'The peacock was unhappy because he didn''t have a voice like the nightingale''s, and he took the complaint to Juno.', '孔雀不痛快，因为他没有夜莺那样的嗓子，就跑去向朱诺抱怨。'),
    (49, 57, 257, '"Every bird alive envies that song," he said. "I open my mouth and I''m a joke."', '“那副歌喉全天下的鸟都眼红，”他说，“我一张嘴就成了笑话。”'),
    (49, 57, 258, 'She tried to reassure him. He had no gift for singing, that was true, but nothing else came close to him for beauty. His neck was emerald. His tail was extraordinary.', '她试着安慰他。会唱歌他是不会，这不假，可论美，没有谁比得上他。他的脖颈像翡翠，他的尾羽美得出奇。'),
    (49, 57, 259, 'It didn''t help. "What good is being beautiful," he said, "with a voice like mine?"', '没用。“长得再美有什么用，”他说，“配上我这条嗓子？”'),
    (49, 57, 260, 'Juno''s tone cooled. "You got beauty, the eagle got strength, the nightingale got the song, and you are the only one of them who has come to me about it, and if I gave you what you''re asking for you''d have found something new to want by morning."', '朱诺的语气冷了下来。“你得了美，鹰得了力气，夜莺得了那副歌喉，只有你一个跑来找我说事；就算我真把你要的给了你，天亮之前你又会有新的不满。”'),
    (50, 58, 261, 'Two young frogs were playing at the edge of a pool when an ox came down to drink and stepped on one of them by accident, killing him.', '两只小青蛙在池边玩，一头牛下来喝水，一脚踩上其中一只，把它踩死了。'),
    (50, 58, 262, 'When the mother frog noticed he was missing, she asked his brother where he was.', '母青蛙发现少了一只，问另一只他弟弟去哪儿了。'),
    (50, 58, 263, '"He''s dead," the little frog said. "Some enormous thing with four legs came to the pool this morning and pushed him into the mud."', '“他死了，”小青蛙说，“今早来了个四条腿的大家伙，把他踩进泥里了。”'),
    (50, 58, 264, '"Enormous? Was he as big as this?" She puffed herself up as far as she could.', '“大家伙？有这么大吗？”她把自己鼓到最大。'),
    (50, 58, 265, '"Much bigger."', '“大得多。”'),
    (50, 58, 266, 'She puffed herself out further. "This big?"', '她又往外鼓了鼓。“这么大？”'),
    (50, 58, 267, '"Bigger, mother. Much bigger."', '“还要大，妈妈。大得多。”'),
    (50, 58, 268, 'She swelled and swelled until she was nearly round. "As big as..."', '她越鼓越大，鼓得快成个球了。“有这么……”'),
    (50, 58, 269, 'Then she burst.', '然后她炸了。'),
    (51, 59, 270, 'A wagoner was driving a full load down a muddy lane when the wheels sank so deep in the mire that his horses couldn''t shift them, no matter how hard they pulled.', '一个车夫赶着满载的车走在泥泞的小路上，车轮陷得太深，马再怎么使劲也拽不动。'),
    (51, 59, 271, 'He stood next to the wagon looking at it, doing nothing, and every few minutes he shouted for Hercules to come and help him.', '他站在车旁看着，什么也不干，每隔一会儿就大声喊赫拉克勒斯来帮忙。'),
    (51, 59, 272, 'Hercules came. "Put your shoulder against the wheel and get your horses moving," he said. "Then call me."', '赫拉克勒斯来了。“用肩膀顶住轮子，把你的马赶起来，”他说，“然后再叫我。”'),
    (52, 60, 273, 'A man and a satyr became friends and decided to live together.', '一个人和一个萨梯交上了朋友，决定住到一块儿。'),
    (52, 60, 274, 'It went fine for a while, until one winter day the satyr watched the man blowing on his hands. "Why are you doing that?"', '起初一切都好，直到一个冬日，萨梯看见那人往手上哈气。“你这是干什么？”'),
    (52, 60, 275, '"To warm them up," the man said.', '“把手暖热，”那人说。'),
    (52, 60, 276, 'At supper that same day they each had a steaming bowl of porridge, and the man lifted his bowl and blew on it.', '当天晚饭，两人各有一碗热气腾腾的粥，那人端起碗来，朝粥上吹气。'),
    (52, 60, 277, '"And why that?" the satyr asked.', '“那又是干什么？”萨梯问。'),
    (52, 60, 278, '"To cool it down."', '“把粥吹凉。”'),
    (52, 60, 279, 'The satyr stood up from the table. "I''m going. I can''t be friends with someone who blows hot and cold out of the same mouth."', '萨梯从桌边站起身。“我走了。同一张嘴又吹热又吹凉的人，我没法跟他做朋友。”'),
    (53, 61, 280, 'An eagle sat on a high rock, watching for prey.', '一只鹰停在高高的岩石上，盯着猎物。'),
    (53, 61, 281, 'A hunter, hidden in a crack in the mountain and watching for game of his own, spotted him and shot.', '一个猎人藏在山石的裂缝里，也在守自己的猎物，一眼看见了他，一箭射了出去。'),
    (53, 61, 282, 'The arrow took him full in the breast and went straight through.', '箭正中前胸，透体而过。'),
    (53, 61, 283, 'Lying there, dying, the eagle turned his head to look at the shaft that had done it.', '鹰倒在那里，快断气了，扭过头去看那支要了他命的箭。'),
    (53, 61, 284, 'It was fletched with eagle feathers.', '箭尾上装的是鹰的羽毛。'),
    (54, 62, 285, 'An old woman picked up an empty wine jar that had once held a rare, expensive wine, and still carried a trace of its scent.', '一个老妇人捡起一只空酒坛，那坛子从前盛过一种珍稀的名贵好酒，如今还留着一丝余香。'),
    (54, 62, 286, 'She held it to her nose and breathed it in, again and again. "If the smell it left behind is this good," she said, "think what the wine must have been."', '她把坛子凑到鼻子跟前，一遍又一遍地闻。“光留下的这点味儿就这么好，”她说，“那当年的酒该是什么样。”'),
    (55, 63, 287, 'A goat wandering through a vineyard started chewing on the young shoots of a vine that was hung with fine bunches of grapes.', '一只山羊在葡萄园里乱逛，啃起一株葡萄藤的嫩芽来，那藤上正挂着好几串上好的葡萄。'),
    (55, 63, 288, '"What did I ever do to you?" the vine said. "Isn''t there grass enough to eat? Strip me bare if you like. When they lead you to the altar to be sacrificed, I''ll still have wine enough to pour over you."', '“我哪里得罪过你？”葡萄藤说，“草还不够你吃吗？你尽管把我啃光。等哪天有人牵你上祭坛宰了你，我照样有的是酒浇在你身上。”'),
    (56, 64, 289, 'Two pots, one clay and one brass, were swept away together in a flooded river.', '两只罐子，一只陶的，一只铜的，被涨水的河一起冲走了。'),
    (56, 64, 290, 'The brass pot told the other to stay close to him and he would look after him.', '铜罐叫陶罐紧挨着自己，说他会护着他。'),
    (56, 64, 291, '"That," said the clay pot, "is exactly what I''m afraid of. One knock from you and there''s nothing left of me."', '“我怕的就是这个，”陶罐说，“你碰我一下，我就什么都不剩了。”'),
    (57, 65, 292, 'A hound who had served his master well for years, and run down more game than he could count, began to lose his strength and his speed to old age.', '一条猎犬为主人尽心效力了许多年，追倒过数不清的猎物，如今上了年纪，力气和脚程都不如从前了。'),
    (57, 65, 293, 'One day out hunting, the master flushed a big wild boar and set the hound on it. The hound caught the boar by the ear, but his teeth were worn down and he couldn''t hold on, and the boar got away.', '有一天出猎，主人惊起一头大野猪，放猎犬去咬。猎犬咬住了野猪的耳朵，可牙齿磨钝了，咬不住，野猪跑了。'),
    (57, 65, 294, 'The master started laying into him, and the hound cut him off. "My will is every bit as strong as it ever was. It''s my body that''s old. Honor me for what I was instead of cursing me for what I''ve become."', '主人张口就骂，猎犬打断了他。“我这颗心跟当年一样硬。老的是我这副身子。你该念我当年的本事，别咒我如今这副样子。”'),
    (58, 66, 295, 'A young hound chased down a hare, and when he caught up with her he couldn''t seem to decide what he was. One moment he''d snap at her as if he meant to kill her, the next he''d let go and frisk around her like he was playing with another dog.', '一条小猎犬追上了一只野兔，追上以后却像拿不定自己是什么。这一下龇牙去咬，像是要她的命；下一下又松开口，绕着她连蹦带跳，像是在跟另一条狗玩。'),
    (58, 66, 296, '"I wish you''d make up your mind," the hare said. "If you''re my friend, why do you keep biting me? If you''re my enemy, why are you playing with me?"', '“我倒希望你拿个准主意，”野兔说，“你要是我的朋友，干吗一口口咬我？你要是我的敌人，又干吗跟我玩闹？”'),
    (59, 67, 297, 'A wolf got a bone stuck in his throat, so he went to a crane and asked her to reach down with her long bill and pull it out. He said he would make it worth her while.', '狼喉咙里卡了根骨头，就去找鹳，请她用那张长喙伸进去把骨头夹出来。他说少不了她的好处。'),
    (59, 67, 298, 'She did it, and the bone came out easily enough.', '她照办了，骨头也没费什么劲就取了出来。'),
    (59, 67, 299, 'The wolf thanked her warmly and was turning to go when she asked about her fee.', '狼千恩万谢，转身要走，她问起说好的酬劳。'),
    (59, 67, 300, '"Your fee?" he said, and showed his teeth. "You put your head inside a wolf''s mouth and got it back. Go tell people that."', '“酬劳？”狼说着龇出牙来，“你把脑袋伸进过狼嘴，又囫囵拿了回去。这事够你到处讲了。”'),
    (60, 68, 301, 'A town mouse and a country mouse knew each other, and one day the country mouse invited his friend out to his place in the fields.', '城里的老鼠和乡下的老鼠认识，有一天乡下老鼠请他到田里的家中做客。'),
    (60, 68, 302, 'Dinner was barley and roots, and the roots tasted like the ground they had come out of.', '晚饭是大麦和根菜，那些根菜吃起来一股土腥味。'),
    (60, 68, 303, 'The guest got through as much as he could stand. "You live no better than the ants out here," he said. "You should see my pantry. Come back with me and I''ll show you what food is."', '客人勉强吃了些。“你在这儿过得还不如蚂蚁，”他说，“你该去看看我的食品间。跟我回去，我让你见识见识什么叫吃的。”'),
    (60, 68, 304, 'So the country mouse went to town, and his friend led him into a larder stocked with flour and oatmeal and figs and honey and dates.', '于是乡下老鼠跟着进了城，朋友把他领进一间储藏室：面粉、燕麦、无花果、蜂蜜、椰枣。'),
    (60, 68, 305, 'He had never seen anything like it. He sat down to eat.', '他这辈子没见过这阵仗。他坐下来就吃。'),
    (60, 68, 306, 'They had barely started when the larder door opened and someone walked in. Both mice bolted and squeezed into a narrow gap that was no place to be.', '刚吃了没几口，储藏室的门开了，有人走了进来。两只老鼠撒腿就跑，挤进一道窄得难受的缝里。'),
    (60, 68, 307, 'When it went quiet they came out again. Someone else came in, and they ran for the gap a second time.', '等外面静下来，他们又出来了。又有人进来，他们第二次往那道缝里钻。'),
    (60, 68, 308, 'That was enough for the visitor. "I''m going home," he said. "You do eat well. But I can eat my roots in peace."', '客人受够了。“我回家了，”他说，“你确实吃得好。可我啃我的根菜，能安安生生啃完。”'),
    (61, 69, 309, 'A stag who was blind in one eye grazed close to the shore, keeping his good eye toward the land so he could watch for the hounds, and turning his blind side to the sea, where he never imagined danger could come from.', '一头瞎了一只眼的鹿在海边吃草，好的那只眼一直朝着陆地，好提防猎狗，把瞎的那侧对着海，他从没想过危险会从海上来。'),
    (61, 69, 310, 'Some sailors rowing along the coast spotted him and put an arrow in him, and the wound was fatal.', '几个沿岸划船的水手瞅见了他，一箭射中，那伤是致命的。'),
    (61, 69, 311, 'He had watched the land, where nothing came for him, and left the sea unwatched, and the sea was what killed him.', '他盯紧了陆地，那边什么也没来；他没设防的是海，要他命的偏偏是海。'),
    (62, 70, 312, 'A rooster scratching around for something to eat turned up a jewel that someone had dropped there.', '一只公鸡刨地找食吃，刨出一颗不知谁掉在那儿的宝石。'),
    (62, 70, 313, '"You''re a fine thing, no doubt," he said. "Whoever lost you would be thrilled to have you back. But I''d trade every jewel in the world for one grain of corn."', '“你想必是个好东西，”他说，“丢了你的人要是找回去，一定高兴坏了。可要我说，天下所有的宝石，我都换一粒谷子。”'),
    (63, 71, 314, 'The parts of the body rebelled against the belly.', '身体的各个部位造了肚子的反。'),
    (63, 71, 315, '"You lie around in comfort and never do a stroke of work," they said. "We do everything, and on top of that we wait on you like servants. We''re finished. Feed yourself."', '“你成天舒舒服服躺着，一点活不干，”它们说，“事都是我们做的，还得像下人一样伺候你。到此为止。你自己去找吃的吧。”'),
    (63, 71, 316, 'They meant it. They left the belly with nothing.', '它们说到做到，什么也不给肚子。'),
    (63, 71, 317, 'Within days the arms had no strength left, the legs wouldn''t hold, and the whole body was going down, and every part that had voted for it went down with it.', '没过几天，胳膊使不上劲，腿撑不住身子，整个身体垮了下去，当初投票的每一个部位都跟着一起垮了。'),
    (64, 72, 318, 'A fly landed on a bald man''s head and bit him.', '一只苍蝇落在一个秃头人的头上，咬了他一口。'),
    (64, 72, 319, 'He swung to kill it and slapped himself hard.', '他抡手去打，结结实实扇了自己一巴掌。'),
    (64, 72, 320, 'The fly got away. "You tried to kill me over one small bite," it said. "What are you going to do to yourself for that one?"', '苍蝇飞了。“就为一小口，你要弄死我，”它说，“那这一下你打算怎么跟自己算账？”'),
    (64, 72, 321, '"Nothing," the man said. "I never meant myself any harm. But for the pleasure of finishing off a bloodsucker like you, I''d have hit myself a good deal harder."', '“不算账，”那人说，“我又不是存心害自己。可要是能拍死你这种吸血的东西，我甘愿再重打几下。”'),
    (65, 73, 322, 'Two travelers were walking a bare, dusty road in the heat of a summer day when they came to a plane tree and gladly turned off to rest in the deep shade of its branches.', '两个旅人在夏日的暑气里走着一条光秃秃、尘土飞扬的路，走到一棵梧桐树下，高高兴兴地拐过去，在它枝叶的浓荫里歇脚。'),
    (65, 73, 323, 'Lying there looking up into it, one of them said, "What a useless tree. No fruit, no good to anybody."', '他躺着往树上看，其中一个说：“这树真没用。不结果子，对谁都没半点好处。”'),
    (65, 73, 324, '"You ungrateful thing," the plane tree said. "You''re lying in my shade this very minute, out of the sun that would roast you, and you call me good for nothing."', '“你这没良心的东西，”梧桐树说，“你这会儿就躺在我的荫凉里，躲着那能把你烤焦的太阳，张口就说我一无是处。”'),
    (66, 74, 325, 'The birds were at war with the beasts, and the fighting went back and forth for a long time without either side settling it.', '鸟和兽打起了仗，来来回回打了很久，谁也没能分出胜负。'),
    (66, 74, 326, 'The bat never committed to either one. When the birds were winning he turned up in their ranks. When the beasts had the upper hand he was found among the beasts.', '蝙蝠始终不站队。鸟占上风时，他就在鸟的队列里；兽占上风时，就在兽中间找得到他。'),
    (66, 74, 327, 'While the war lasted, nobody paid him any attention.', '打仗的那些日子，没人顾得上理他。'),
    (66, 74, 328, 'When it ended and the two sides made peace, neither of them would have anything to do with him, and he has been on his own ever since.', '等仗打完、两边讲和，谁都不肯再跟他来往，从那以后他就一直是孤零零一个。'),
    (67, 75, 329, 'A miller and his young son were driving their donkey to market, hoping to sell him.', '磨坊主带着小儿子赶驴去集市，想把驴卖了。'),
    (67, 75, 330, 'On the road they passed a group of girls, laughing and talking, and one of them called out, "Look at those two fools, walking through the dust when they''ve got something to ride."', '路上他们碰见一群姑娘，说说笑笑，其中一个喊道：“瞧那两个傻子，有驴不骑，偏要一路吃土走过去。”'),
    (67, 75, 331, 'The miller decided she had a point, so he put his son on the donkey and walked alongside.', '磨坊主觉得有道理，就让儿子骑上驴，自己在旁边走。'),
    (67, 75, 332, 'Farther on they met some men the miller knew. "You''ll ruin that boy, letting him ride while you wear yourself out on foot. Get him down and make him walk."', '又走了一程，遇上几个熟人。“你这么惯着孩子，早晚把他惯坏。他骑着，你在下面累死累活。把他弄下来，让他自己走。”'),
    (67, 75, 333, 'The miller took their advice, put his son on the ground and himself on the donkey''s back.', '磨坊主听了他们的，把儿子放下地，自己坐上了驴背。'),
    (67, 75, 334, 'Not long after, they caught up with a group of women and children, and he heard one of them say, "What a selfish old man. He rides in comfort and lets that poor little boy keep up on his own legs."', '没过多久又赶上一群妇女和孩子，他听见其中一个说：“这老头真自私。自己骑得舒舒服服，让那么小的孩子在下面跟着跑。”'),
    (67, 75, 335, 'So he pulled his son up behind him.', '于是他又把儿子拉上来坐在身后。'),
    (67, 75, 336, 'Later they met some travelers, who asked whether the donkey was his own or hired. He said it was his, and that he was taking it to market to sell. "With that load on him? He''ll be so worn out by the time you get there that nobody will look at him twice. You''d do better carrying him."', '后来遇上几个赶路人，问那驴是他自己的还是租的。他说是自己的，正要牵去集上卖。“驮着这么两个人？等你到了，它累得不成样子，谁还会多看它一眼。你不如把它扛着走。”'),
    (67, 75, 337, '"Anything to keep people happy," the miller said. "We can try."', '“只要各位满意，”磨坊主说，“试试就试试。”'),
    (67, 75, 338, 'They got down, tied the donkey''s legs together, slung him from a pole, and carried him between them the rest of the way into town.', '他们下了驴，把驴腿绑在一起，拿根杆子穿着，两人抬着它走完了进城的路。'),
    (67, 75, 339, 'People came running out to look and laugh, and some of them shouted that the two of them were out of their minds.', '人们跑出来看热闹、看笑话，还有人冲他们喊，说这两个人是疯了。'),
    (67, 75, 340, 'They were on the bridge over the river when the donkey, frightened by the noise and by hanging upside down from a pole, kicked hard enough to break the ropes, went over the side, and drowned.', '走到河上的桥面时，驴被那阵吵闹和倒吊在杆上的姿势惊着了，一通乱踢，挣断了绳子，翻过桥栏掉进水里淹死了。'),
    (67, 75, 341, 'The miller walked home with his son and nothing else.', '磨坊主带着儿子回了家，别的什么也没带回去。'),
    (68, 76, 342, 'A stag being chased by huntsmen hid himself under a thick vine, and they lost the trail and went right past without knowing he was there.', '一头被猎人追赶的鹿，躲进了一丛茂密的葡萄藤下，猎人跟丢了，径直从他藏身处走了过去，没察觉他就在近旁。'),
    (68, 76, 343, 'Thinking the danger had passed, he started nibbling the leaves of the vine.', '他以为危险过去了，就啃起那藤上的叶子来。'),
    (68, 76, 344, 'The rustling turned the huntsmen back around. One of them, guessing something was hidden in there, shot an arrow blind into the leaves, and it went through the stag''s heart.', '那窸窣声把猎人引了回来。其中一个猜到叶子里藏着什么，朝丛中盲射一箭，正穿透了鹿的心。'),
    (68, 76, 345, 'The cover that had saved him was the thing he couldn''t leave alone.', '救过他一命的藏身之处，偏偏是他忍不住要糟践的东西。'),
    (69, 77, 346, 'There was an astronomer who went out every night to watch the stars.', '从前有个天文学家，每天夜里都要出门观星。'),
    (69, 77, 347, 'One night, walking outside the town gates with his eyes on the sky and no attention on anything else, he went straight into a dry well.', '有一晚，他走在城门外，眼睛盯着天，别的什么都没留神，一脚踏空掉进了一口枯井。'),
    (69, 77, 348, 'He was lying at the bottom groaning when someone passing heard him and came to the edge to look down.', '他躺在井底哼哼，一个路过的人听见了，走到井边往下看。'),
    (69, 77, 349, '"You were watching the sky so closely that you couldn''t see the ground under your own feet," the man said. "Then I''d say you''ve got exactly what you were owed."', '“你盯着天看得那么认真，连自己脚底下都看不见，”那人说，“那我看你落到这步，一点不冤。”'),
    (70, 78, 350, 'A laborer''s little boy was bitten by a snake and died.', '一个雇工的小儿子被蛇咬了，死了。'),
    (70, 78, 351, 'The father, out of his mind with grief and rage, took an ax and went and stood by the snake''s hole, waiting for a chance at it.', '父亲又悲又恨，几乎失了神智，抄起斧子守在蛇洞边，等着下手的机会。'),
    (70, 78, 352, 'When the snake came out he swung, and caught nothing but the tip of its tail before it slid back in.', '蛇一出来他就砍，只砍下了一截尾巴尖，蛇又缩了回去。'),
    (70, 78, 353, 'After that he tried to coax it out again, saying he wanted to put the quarrel behind them.', '后来他改口哄它出来，说这事就此揭过。'),
    (70, 78, 354, '"I can''t be your friend with my tail gone," the snake said, "and you can''t be mine with your child gone."', '“我少了尾巴，做不成你的朋友，”蛇说，“你少了孩子，也做不成我的。”'),
    (71, 79, 355, 'A young goat had wandered off from the flock and a wolf was chasing him down.', '一只小山羊离了群，一只狼正追着他不放。'),
    (71, 79, 356, 'Seeing there was no getting away, the goat turned around. "I know you''re going to eat me, sir. Since I don''t have long, let me at least go out happy. Play me a tune and let me dance before I die."', '眼看逃不掉，小山羊回过身来。“先生，我知道我逃不过要被你吃掉。反正也活不长了，那就让我痛痛快快地走。你吹支曲子，让我在死前跳一场吧。”'),
    (71, 79, 357, 'The wolf saw no harm in a little music before dinner, so he took out his pipe and played while the goat danced.', '狼觉得开饭前来点音乐没什么不好，就掏出笛子吹起来，小山羊在一旁跳。'),
    (71, 79, 358, 'The dogs guarding the flock heard the pipe and came to see what was going on, and the moment they saw the wolf they ran him off.', '看守羊群的狗听见笛声，跑来看是怎么回事，一看见狼，立刻把他撵走了。'),
    (71, 79, 359, '"Serves me right," the wolf said as he ran. "I''m a butcher. I had no business turning piper."', '“活该，”狼一边跑一边说，“我是干屠户这行的，本就不该去当什么吹笛人。”'),
    (72, 80, 360, 'A man who had lost all his hair started wearing a wig, and one day he went out hunting.', '一个头发掉光的人开始戴假发，有一天他出门打猎。'),
    (72, 80, 361, 'The wind was up, and he hadn''t gone far before a gust took his hat, and the wig went with it, to the delight of everyone riding with him.', '那天风大，没走多远一阵风就把他的帽子掀走了，假发也跟着走了，同行的人乐得不行。'),
    (72, 80, 362, 'He laughed along with them. "The hair that wig is made of wouldn''t stay on the head it grew on," he said. "I can hardly expect it to stay on mine."', '他跟着一起笑。“这假发上的头发，长在谁头上都没留住，”他说，“凭什么指望它留在我头上。”'),
    (73, 81, 363, 'A man had two daughters. One married a gardener and the other married a potter.', '一个人有两个女儿。一个嫁了花匠，一个嫁了陶匠。'),
    (73, 81, 364, 'After a while he went to see how they were doing, starting with the gardener''s wife.', '过了些日子他去看看她们过得怎么样，先去了花匠家。'),
    (73, 81, 365, 'She said things were going well enough on the whole. "I only wish we''d get some good rain," she said. "The garden needs it badly."', '大女儿说日子大体上过得不错。“就盼着能下场好雨，”她说，“园子等着用水呢。”'),
    (73, 81, 366, 'Then he went to the potter''s wife and asked the same questions. She said she and her husband had no complaints. "I only wish we''d get a good dry spell," she said. "The pottery has to dry."', '接着他去了陶匠家，问了同样的话。二女儿说她和丈夫没什么可抱怨的。“就盼着能连着晴几天，”她说，“陶器得晾干。”'),
    (73, 81, 367, 'Her father gave her a look. "You want dry weather and your sister wants rain," he said. "I was going to pray that you both got what you wanted. I think I''ll leave the subject alone."', '父亲看了她一眼。“你要晴，你姐姐要雨，”他说，“我本来打算求神让你们各得所愿。这事我看还是别提了。”'),
    (74, 82, 368, 'A wild donkey, out roaming with nothing to do, came across a pack donkey stretched out in a sunny spot, taking his ease.', '一头野驴正闲逛着无事可做，遇见一头驮货的驴摊开身子躺在向阳的地方，舒舒服服。'),
    (74, 82, 369, '"What a lucky animal you are," he said. "That sleek coat says how well you''re fed. I envy you."', '“你这牲口真有福气，”他说，“瞧你这身油光水滑的毛，就知道你吃得多好。我真羡慕你。”'),
    (74, 82, 370, 'Not long after, he saw him again, this time under a heavy load with a driver walking behind and laying into him with a thick stick.', '没过多久他又看见了他，这一回那驴驮着沉甸甸的货，赶驴的跟在后头，抡着根粗棍子朝他身上打。'),
    (74, 82, 371, '"I don''t envy you anymore," the wild donkey said. "I can see now what those comforts cost you."', '“我不再羡慕你了，”野驴说，“如今我看清了，你那点舒坦是拿什么换来的。”'),
    (75, 83, 372, 'Two frogs lived together in a marsh, but one hot summer the marsh dried up and they set off to find somewhere else, since frogs go for damp places when they can get them.', '两只青蛙一起住在一片沼泽里，可有一年夏天太热，沼泽干了，它们便动身另找去处，青蛙但凡有得选，总爱往潮湿的地方去。'),
    (75, 83, 373, 'They came to a deep well, and one of them looked down and said, "This looks nice and cool. Let''s jump in and stay here."', '它们来到一口深井边，一只往下看了看说：“这里又凉快又舒服。咱们跳下去，就在这儿住吧。”'),
    (75, 83, 374, '"Not so fast," said the other, who had the better head of the two. "Suppose this well dries up like the marsh did. How would we ever get out?"', '“别急，”另一只说，它是两个里头脑子清楚些的那个，“万一这井也像那沼泽一样干了呢？咱们又怎么爬得上来？”'),
    (76, 84, 375, 'A shepherd found a wolf cub wandering in the pastures, took him home, and raised him with the dogs.', '牧人在草场上捡到一只走失的狼崽，带回家，和狗一起养大。'),
    (76, 84, 376, 'Once the wolf was full grown, he would go out with the dogs whenever a sheep was taken and help hunt the thief down.', '狼长成之后，羊群里一丢羊，他就跟着狗一起出去追赃。'),
    (76, 84, 377, 'Sometimes the dogs lost the trail and gave up and came home. The wolf would keep going on his own, and when he caught up with the thief he would sit down and share the meal with him, and then go back to the shepherd.', '有时狗跟丢了，放弃回家，他会自己接着追，追上了就坐下来和贼分食，然后回到牧人那里。'),
    (76, 84, 378, 'And if too long went by without any wolf taking a sheep, he would take one himself and split it with the dogs.', '要是隔了太久没有狼来叼羊，他就自己叼一只，再和狗分了。'),
    (76, 84, 379, 'The shepherd started to wonder. One day he caught him at it, put a rope around his neck, and hanged him from the nearest tree.', '牧人起了疑。有一天他当场抓住了他，拿绳子套住脖子，吊死在最近的一棵树上。'),
    (77, 85, 380, 'The rivers got together to complain about the sea for turning their water salty.', '河流们聚到一起，抱怨大海把它们的水变咸了。'),
    (77, 85, 381, '"When we reach you we''re fresh and good to drink," they said. "The moment we mix with you we turn as briny and undrinkable as you are."', '“我们流到你这儿的时候，又清又甜，能喝，”它们说，“可一跟你汇到一处，就变得跟你一样又咸又苦，没法入口。”'),
    (77, 85, 382, '"Then stay away from me," the sea said, "and you''ll stay sweet."', '“那就别靠近我，”大海说，“你们自会一直清甜。”'),
    (78, 86, 383, 'A lion fell hard for a cottager''s daughter and wanted to marry her.', '一头狮子爱上了一户农家的女儿，非要娶她。'),
    (78, 86, 384, 'Her father had no intention of handing his daughter to a husband like that, and no intention of insulting a lion either, so he worked out a way around it.', '当爹的绝不肯把女儿交给这样一个丈夫，可也绝不敢得罪一头狮子，于是想了个绕开去的法子。'),
    (78, 86, 385, 'He went to the lion. "I think you''d make my daughter a fine husband," he said. "But I can''t agree to it unless you let me pull your teeth and cut your claws back. She''s terrified of them."', '他去找狮子。“我看你给我女儿当丈夫是够格的，”他说，“可你得让我把你的牙拔了、爪子剪短，我才能点头。她怕那些东西怕得要命。”'),
    (78, 86, 386, 'The lion was too far gone to argue, and let it be done.', '狮子早已昏了头，二话不说就让他动了手。'),
    (78, 86, 387, 'Once he was disarmed, the cottager wasn''t afraid of him anymore, and drove him off the property with a club.', '等他没了牙也没了爪，农夫再不怕他，抄起棍子把他打出了家门。'),
    (79, 87, 388, 'A dog was lying in the sun outside a farmyard gate when a wolf jumped him and was about to eat him.', '一条狗躺在农家院门外晒太阳，一只狼扑上来，正要把他吃掉。'),
    (79, 87, 389, 'The dog talked fast. "Look how thin I am. There''s nothing on me worth eating. My master is throwing a feast in a few days and all the good scraps come to me. Wait, and I''ll be worth the trouble."', '狗嘴快。“你看我瘦成这样，身上哪有什么可吃的。过几天我主人办宴席，好东西的下脚料都归我。你等等，那时候吃我才划算。”'),
    (79, 87, 390, 'The wolf thought that sounded reasonable and left.', '狼觉得有道理，就走了。'),
    (79, 87, 391, 'He came back some time later and found the dog lying on the stable roof, well out of reach.', '过了些日子他又来了，看见那条狗躺在马厩顶上，够都够不着。'),
    (79, 87, 392, '"Come down and be eaten," he called. "We had an arrangement."', '“下来让我吃，”他喊，“我们说好的。”'),
    (79, 87, 393, '"My friend," the dog said, "if you ever catch me lying by that gate again, don''t wait for any feast."', '“朋友，”狗说，“下回你要是再在那道门边逮着我躺着，就别等什么宴席了。”'),
    (80, 88, 394, 'A swan is said to sing just once, when it knows it is about to die.', '据说天鹅一生只唱一次，就在它知道自己将死的时候。'),
    (80, 88, 395, 'A man who had heard about this saw a swan for sale at the market, bought it, and took it home.', '一个听说过这事的人，在市集上看见一只待售的天鹅，买下来带回了家。'),
    (80, 88, 396, 'A few days later he had friends over for dinner and brought the swan out to sing for them, but it wouldn''t make a sound.', '过了几天他请朋友来吃饭，把天鹅牵出来给大家唱歌，它却一声也不出。'),
    (80, 88, 397, 'In time the swan grew old, and when it felt the end coming it broke into a low, sweet, sorrowful song.', '后来天鹅老了，等它感到大限将至，便唱起一支低回、婉转、凄切的歌。'),
    (80, 88, 398, 'Its owner heard it. "If it only sings when it''s dying," he said, "I was a fool to ask for a song that night. I should have wrung its neck."', '主人听见了。“既然它只在临死才唱，”他说，“那晚我要它唱歌真是个傻瓜。我早该拧断它的脖子。”'),
    (81, 89, 399, 'An eagle and a fox became close friends and decided to live near each other, on the theory that the more they saw of one another the better it would be.', '一只鹰和一只狐狸成了好朋友，商量着住得近些，觉得往来越多，交情就越好。'),
    (81, 89, 400, 'The eagle built her nest at the top of a tall tree. The fox settled in the thicket at the foot of it and had a litter of cubs.', '鹰把巢筑在一棵高树的顶上。狐狸在树脚的灌木丛里安了家，生了一窝小崽。'),
    (81, 89, 401, 'One day, while the fox was out hunting for food, the eagle went down into the thicket, took the cubs, and carried them up to the nest for herself and her young.', '有一天狐狸出去找食，鹰飞进灌木丛，把那窝小崽叼走，带回巢里喂自己和雏鸟。'),
    (81, 89, 402, 'The fox came back and worked out what had happened. What she felt was less grief than fury, because there was nothing she could do. She couldn''t climb, and she couldn''t reach the eagle. She sat down within sight of the tree and cursed her.', '狐狸回来，弄明白了是怎么回事。她心里更多的不是伤心而是恨，因为她拿对方毫无办法。她爬不上去，够不着那只鹰。她在望得见那棵树的地方坐下，一句句咒她。'),
    (81, 89, 403, 'She didn''t have to wait long.', '她没等太久。'),
    (81, 89, 404, 'Some villagers were sacrificing a goat at an altar nearby, and the eagle flew down and carried a piece of burning meat back to the nest.', '附近有村民在祭坛上献祭一只山羊，鹰飞下去叼了一块带火的肉回巢。'),
    (81, 89, 405, 'The wind was strong. The nest caught, and her half-roasted fledglings dropped to the ground.', '那天风大。巢烧了起来，烤得半熟的雏鸟掉到了地上。'),
    (81, 89, 406, 'The fox came out and ate them in front of her.', '狐狸走出来，当着她的面把它们吃了。'),
    (82, 90, 407, 'A fox swimming across a fast river was pulled under by the current and carried a long way down before he managed to drag himself out onto dry ground, bruised and finished.', '一只狐狸游过一条急流，被水卷走，冲出去很远，最后好不容易从一处回水湾爬上岸，浑身是伤，力气耗尽。'),
    (82, 90, 408, 'He lay there unable to move while a swarm of horseflies settled on him and drank, and he was too weak to shake them off.', '他瘫在那儿动弹不得，一群马蝇落到他身上吸血，他虚弱得连赶都赶不动。'),
    (82, 90, 409, 'A hedgehog found him and offered to brush them away.', '一只刺猬看见了，问要不要替他把蝇子扫掉。'),
    (82, 90, 410, '"Please don''t," the fox said. "These ones have had their fill and are barely taking anything now. Drive them off and a hungry swarm comes next, and they''ll finish what''s left in me."', '“千万别，”狐狸说，“这些已经吸饱了，现在几乎不再取我什么。你把它们赶走，下一批饿着的就来了，我身上剩的那点会被吸干净。”'),
    (83, 91, 411, 'A witch made her living claiming she could turn away the anger of the gods with charms only she knew, and business was good.', '一个女巫靠一张嘴过活，说自己会用只有她才懂的符咒平息神明的怒气，生意还很兴隆。'),
    (83, 91, 412, 'Then some people accused her of dark magic, hauled her before the judges, and demanded she be put to death for dealing with the devil. She was found guilty and sentenced.', '后来有人告她使黑巫术，把她扭送到法官面前，要求以通魔之罪处她死刑。她被判有罪，定了死。'),
    (83, 91, 413, 'As she was led away, one of the judges said, "You claim you can turn away the anger of the gods. How is it you couldn''t turn away the anger of your neighbors?"', '她被带下去时，一个法官说：“你说你能平息神明的怒气。怎么连身边这些人的怒气都平息不了？”'),
    (84, 92, 414, 'An old man cut a bundle of sticks in the woods and started carrying it home.', '一个老人在林子里砍了一捆柴，背着往家走。'),
    (84, 92, 415, 'He had a long way to go and was worn out before he was much past halfway.', '路很长，还没走过一半多少，他就累垮了。'),
    (84, 92, 416, 'He dropped the bundle on the ground and called on Death to come and take him out of a life of hauling.', '他把柴往地上一扔，喊死神来把他从这种成天卖力气的日子里解脱出去。'),
    (84, 92, 417, 'The words were barely out when Death was standing in front of him, ready to oblige.', '话音还没落，死神就站在了他面前，说来听候吩咐。'),
    (84, 92, 418, 'The old man was frightened nearly out of his mind, but he kept enough of it to say, "Good sir, if you''d be so kind, could you help me get this back on my shoulder?"', '老人吓得快没了魂，好歹还剩一点，结结巴巴说：“劳驾您行行好，帮我把这捆柴重新架到肩上吧。”'),
    (85, 93, 419, 'A miser sold everything he owned, melted his gold down into one lump, and buried it in a field where nobody would find it.', '一个守财奴把家当全卖了，把金子熔成一整块，埋在一片没人会去的田里。'),
    (85, 93, 420, 'He went to look at it every day, and sometimes stood over the spot for hours.', '他每天都去看一眼，有时候在那块地上一站就是几个钟头。'),
    (85, 93, 421, 'One of his workers noticed how often he went out there, followed him one day, and found out why.', '他手下有个人留意到他老往那边跑，有一天跟了过去，弄清了原委。'),
    (85, 93, 422, 'He waited for his chance, came back at night, dug the gold up, and took it.', '他等着机会，夜里回去把金子挖出来带走了。'),
    (85, 93, 423, 'The next day the miser went out as usual, found the hole empty, and stood there tearing at his hair.', '第二天守财奴照例过去，发现坑空了，站在那儿直揪自己的头发。'),
    (85, 93, 424, 'A neighbor came by and asked what was wrong, and the miser told him.', '一个邻居路过，问他出了什么事，他说了。'),
    (85, 93, 425, '"Don''t take it so hard," the neighbor said. "Put a brick in the hole and come look at it every day. It''ll do you exactly as much good as the gold did."', '“别太往心里去，”邻居说，“往坑里放块砖，照样每天来看一眼。那跟你埋着金子的时候，对你的用处一模一样。”'),
    (86, 94, 426, 'A horse had a meadow to himself and grazed it alone.', '一匹马独占着一片草场，一个人吃草。'),
    (86, 94, 427, 'Then a stag turned up, said he had as much right to the grass as anyone, and took the best of it for himself.', '后来来了一头鹿，说这草他也有份，还专挑最好的地方吃。'),
    (86, 94, 428, 'The horse wanted him gone. He went to a man and asked for help driving the stag out.', '马想把他赶走。他去找了个人，请他帮忙把鹿轰出去。'),
    (86, 94, 429, '"I''ll do it," the man said. "But only if you let me put a bridle in your mouth and get on your back."', '“可以，”那人说，“但你得让我把嚼子放进你嘴里，让我骑上你的背。”'),
    (86, 94, 430, 'The horse agreed, and between them they had the stag out of the pasture in no time.', '马答应了，两个一起，没多久就把鹿赶出了草场。'),
    (86, 94, 431, 'And when it was done, the horse understood that he had acquired a master for the rest of his life.', '事情办完，马才明白，自己这辈子从此有了主人。'),
    (87, 95, 432, 'A man digging over his vineyard came to work one day and found his spade missing.', '一个在自家葡萄园翻土的人，有一天来干活，发现铲子不见了。'),
    (87, 95, 433, 'Sure one of his workers had taken it, he questioned them hard, and every one of them swore he knew nothing about it.', '他认定是手下哪个雇工偷了，把他们盘问了个遍，人人都赌咒说毫不知情。'),
    (87, 95, 434, 'He didn''t believe them, and marched them all into town to swear their innocence in a temple, because he thought little of the simple country gods and figured the sharper town gods would catch the thief out.', '他不信，把他们一股脑赶进城，要他们在庙里起誓表明清白，因为他瞧不上乡下那些没见识的神，觉得城里的神精明些，能把贼揪出来。'),
    (87, 95, 435, 'The first thing they heard inside the gates was the town crier offering a reward for anyone who could name the thief who had robbed the city temple.', '进了城门，头一样听见的就是宣令官在悬赏，求人指认那个偷了城中神庙的贼。'),
    (87, 95, 436, '"I think I''ll head home," the man said to himself. "If these town gods can''t catch the thieves who rob their own temple, they''re hardly going to tell me who took my spade."', '“我看还是回家去吧，”那人自语道，“连偷他们自己庙的贼都抓不住，这城里的神哪还说得出是谁拿了我的铲子。”'),
    (88, 96, 437, 'Jupiter told Prometheus to make man and the other animals, and Prometheus set to work.', '朱庇特吩咐普罗米修斯造人和别的动物，普罗米修斯就动了手。'),
    (88, 96, 438, 'When it was done, Jupiter saw that the one rational creature was hopelessly outnumbered by the rest, and told him to even things out by turning some of the animals into men.', '造完之后，朱庇特看到唯一有理性的那一种在数量上远远吃亏，就叫他把一部分动物改成人，把数目扯平。'),
    (88, 96, 439, 'Prometheus did as he was told.', '普罗米修斯照办了。'),
    (88, 96, 440, 'That is why some people have the shape of a man and the soul of an animal.', '所以有些人长着人的样子，装着野兽的心。'),
    (89, 97, 441, 'A traveler worn out from a long journey lay down right at the edge of a deep well and fell asleep.', '一个赶了远路、累得不行的旅人，就在一口深井的边上躺下，睡着了。'),
    (89, 97, 442, 'He was a hair from rolling in when Lady Fortune came and touched his shoulder, waking him and warning him to move back.', '他离滚进井里只差一丝一毫，命运女神来到他身边，碰了碰他的肩，把他叫醒，劝他往后挪一挪。'),
    (89, 97, 443, '"Wake up, good sir," she said. "If you''d fallen in, no one would have blamed your own carelessness. They''d have blamed me."', '“醒醒，好心的先生，”她说，“你要是掉了下去，没人会怪你自己不小心。他们只会怪我。”')
) AS v(chapter_idx, para_idx, seq, text_en, text_cn)
WHERE b.book_key = 'aesop-easy-readers';

SELECT 'after' AS phase,
       (SELECT sentence_count FROM public.library_books WHERE book_key = 'aesop-easy-readers') AS book_sentence_count,
       (SELECT count(*) FROM public.library_sentences s
          JOIN public.library_books b ON b.id = s.book_id
         WHERE b.book_key = 'aesop-easy-readers') AS sentence_rows;

COMMIT;

-- 审核通过后,单独跑这一行让样书对用户可见(软上线):
-- UPDATE public.library_books SET is_published = true WHERE book_key = 'aesop-easy-readers';
